window.TXB=window.TXB||{};TXB["alab/1Sa"]={"1:1":"كان رجل أفرايمي اسمه ألقانة بن يروحام بن أليهو بن توحو بن صوف، يقيم في رامتايم صوفيم من جبل أفرايم.","1:2":"وكان متزوجا من امرأتين هما حنة وفننة. وكان لفننة أولاد؛ أما حنة فكانت عاقرا.","1:3":"وكان من عادة ألقانة أن يذهب من مدينته مع عائلته في كل عام ليسجد ويقدم ذبائح للرب القدير في شيلوه، وكان حفني وفينحاس ابنا عالي كاهنين للرب في ذلك الوقت.","1:4":"وحين يأتي وقت تقديم الذبيحة كان ألقانة يعطي فننة امرأته وجميع أبنائها وبناتها نصيبا واحدا لكل منهم.","1:5":"أما حنة فكان يعطيها نصيب اثنين لأنه كان يحبها. غير أن الرب جعلها عاقرا.","1:6":"فكانت ضرتها، حبا في إغاظتها، تعيرها لأن الرب جعلها عاقرا.","1:7":"وثابرت على إثارة غيظها سنة بعد سنة كلما ذهبت إلى بيت الرب. فبكت حنة وامتنعت عن الأكل.","1:8":"فسألها ألقانة زوجها: «يا حنة، لماذا تبكين؟ ولماذا تمتنعين عن الأكل؟ ولماذا يكتئب قلبك؟ ألست أنا خيرا لك من عشرة بنين؟»","1:9":"وذات مرة بعد أن فرغوا من تناول الطعام في شيلوه، وفيما كان عالي الكاهن جالسا على الكرسي عند قائمة خيمة الرب، قامت حنة","1:10":"بنفس مرة وصلت إلى الرب وبكت بحرقة،","1:11":"ونذرت نذرا للرب قائلة: «يا رب الجنود، إن عطفت على مذلة أمتك، وذكرتني ولم تنسني، بل وهبت أمتك ذرية، فإنني أعطيه للرب كل أيام حياته، ولن أحلق رأسه».","1:12":"وأطالت حنة صلاتها أمام الرب بينما كان عالي يراقب حركة شفتيها.","1:13":"فإن حنة كانت تصلي في قلبها ولا يتحرك منها سوى شفتيها، من غير أن يصدر عنهما صوت، فظن عالي أنها سكرى.","1:14":"فقال لها عالي: «إلى متى تظلين سكرى؟ كفي عن شرب الخمر»","1:15":"فأجابته: «لا يا سيدي: إنني امرأة حزينة الروح، لم أشرب خمرا ولا مسكرا، بل أسكب نفسي أمام الرب.","1:16":"لا تظن أمتك ابنة بليعال، فإنني من فرط كربتي وغيظي قد أطلت صلاتي إلى الآن».","1:17":"فقال لها عالي: «اذهبي بسلام، وليعطك إله إسرائيل ما طلبته من لدنه».","1:18":"فقالت: «ليت أمتك تحظى برضاك». ثم انصرفت في سبيلها وأكلت، ولم تعد أمارات الحزن تكسو وجهها.","1:19":"وفي الصباح التالي بكروا بالنهوض وسجدوا أمام الرب، ثم عادوا إلى بيتهم في الرامة. وعاشر ألقانة زوجته حنة، واستجاب الرب دعاءها.","1:20":"وفي غضون سنة حبلت حنة وأنجبت ابنا دعته صموئيل قائلة: «لأني سألته من الرب».","1:21":"وفي موعد الذبيحة السنوية من العام التالي، ذهب ألقانة وأسرته للعبادة.","1:22":"غير أن حنة تخلفت عنهم قائلة لزوجها: «سأنتظر حتى أفطم الصبي، ثم آخذه ليمثل أمام الرب، وأتركه هناك إلى الأبد».","1:23":"فأجابها ألقانة: «افعلي ما يحلو لك، وامكثي حتى تفطميه، ويكفينا أن الرب يفي بما وعد به». فمكثت حنة في بيتها ترضع ابنها إلى أن فطمته.","1:24":"ثم انطلقت بالصبي، على الرغم من صغر سنه، إلى الرب في شيلوه، ومعها ثلاثة ثيران وإيفة دقيق (نحو أربعة وعشرين لترا) وزق خمر.","1:25":"وبعد أن ذبحوا الثور حملوا الصبي إلى عالي،","1:26":"وقالت له: «لتحي نفسك يا سيدي، أنا المرأة التي مثلت لديك هنا تصلي إلى الرب،","1:27":"متضرعة إليه أن يعطيني هذا الصبي، فاستجاب الرب دعائي الذي رفعته إليه.","1:28":"لذلك أنا أهبه للرب جميع أيام حياته». وسجدوا هناك للرب.","2:1":"وصلت حنة قائلة: «ابتهج قلبي بالرب وسمت عزتي به. أفتخر على أعدائي لأني فرحت بخلاصك.","2:2":"إذ ليس قدوس نظير الرب، ولا يوجد من يماثلك، وليس صخرة كإلهنا.","2:3":"كفوا عن الكبرياء، وكموا أفواهكم عن الغرور لأن الرب إله عليم وبه توزن الأعمال.","2:4":"لقد تحطمت أقواس الجبابرة وتنطق الضعفاء بالقوة.","2:5":"الذين كانوا شباعى آجروا أنفسهم لقاء الطعام، والذين كانوا جياعا ملأهم الشبع. أنجبت العاقر سبعة، أما كثيرة الأبناء فقد ذبلت.","2:6":"الرب يميت ويحيي، يطرح إلى الهاوية ويصعد منها.","2:7":"الرب يفقر ويغني، يذل ويعز.","2:8":"ينهض المسكين من التراب، ويرفع البائس من كومة الرماد، ليجلسه مع النبلاء، ويملكه عرش المجد، لأن للرب أساسات الأرض التي أرسى عليها المسكونة.","2:9":"هو يحفظ أقدام أتقيائه، أما الأشرار فينطوون في الظلام، لأنه ليس بالقوة يتغلب الإنسان.","2:10":"مخاصمو الرب يتحطمون، ومن السماء يقذف رعوده عليهم؛ يدين الرب أقاصي الأرض، ويمنح عزة لمن يختاره ملكا ويمجد مسيحه».","2:11":"ثم رجع ألقانة إلى بيته في الرامة، وظل الصبي يخدم الرب لدى عالي الكاهن.","2:12":"أما ابنا عالي فكانا متورطين في الشر لا يعرفان الرب","2:13":"ولا حق الكهنة المتوجب على الشعب. فكان كلما قدم رجل ذبيحة يأتي غلام الكاهن عند طبخ اللحم حاملا بيده خطافا ذا ثلاث شعب.","2:14":"فيغرزه في اللحم الذي في المرحضة أو المرجل أو المقلى أو القدر، ويأخذ الكاهن كل ما يعلق بشعب الخطاف. هكذا كانا يعاملان جميع الإسرائيليين القادمين إلى شيلوه.","2:15":"كذلك كان خادم الكاهن يأتي إلى ذابح القربان ويقول له قبل إحراق الشحم: «أعط لحما للكاهن حتى يشوى، فإنه لا يقبل منك لحما مطبوخا بل نيئا».","2:16":"فيجيبه الرجل: «ليحرقوا أولا شحم الذبيحة، ثم خذ ما تشتهيه نفسك». فيقول الخادم: «لا، بل أعطني الآن اللحم وإلا آخذه بالرغم عنك».","2:17":"فعظمت خطيئة أبناء عالي أمام الرب، لأن الشعب استهان بذبيحة الرب من جراء تصرفاتهما.","2:18":"وكان صموئيل آنئذ يخدم في محضر الرب وهو ما برح صبيا، يرتدي أفودا من كتان.","2:19":"وكانت أمه تصنع له جبة صغيرة، تحضرها معها كل سنة عند مجيء رجلها لتقريب الذبيحة السنوية،","2:20":"فيبارك عالي ألقانة وزوجته قائلا: «ليرزقك الرب ذرية من هذه المرأة عوضا عن الصبي الذي وهبتماه للرب». ثم يرجعان إلى حيث يقيمان.","2:21":"وعندما افتقد الرب حنة، حملت وأنجبت ثلاثة أبناء وبنتين. أما صموئيل فقد ترعرع في خدمة الرب.","2:22":"وطعن عالي في السن. وبلغه ما ارتكبه بنوه من مساوئ بحق جميع الإسرائيليين، وأنهم كانوا يضاجعون النساء المجتمعات عند مدخل خيمة الاجتماع.","2:23":"فقال لهم: «لماذا ترتكبون هذه الفواحش، فقد بلغتني أخبار مساوئكم من جميع هذا الشعب؟","2:24":"لا، يا بني، فالأخبار التي بلغتني مشينة، إذ إنكم تجعلون الشعب يتعدى على شريعة الرب.","2:25":"فإن أخطأ إنسان نحو إنسان، فالله يدينه، ولكن إن أخطأ إلى الرب فمن يصلي من أجله؟» لكنهم لم يعيروا توبيخ أبيهم أي اهتمام لأن الرب شاء أن يميتهم.","2:26":"أما الصبي صموئيل فاستمر ينمو في الصلاح ويحظى برضى الله والناس.","2:27":"وذات يوم جاء نبي إلى عالي برسالة من الله، قال: «ألم أتجل لبيت أبيك وهم ما برحوا في مصر في ديار فرعون،","2:28":"وانتخبت أباكم هرون من بين جميع أسباط إسرائيل ليكون لي كاهنا يصعد على مذبحي قرابين ويوقد بخورا، ويرتدي أمامي أفودا، ووهبت لبيت أبيك جميع وقائد بني إسرائيل.","2:29":"فلماذا تحتقرون ذبيحتي وتقدمتي التي أمرت بها للمسكن، وتفضل ابنيك عني لتكدسوا الشحم على أبدانكم، مما تخيرتموه من قرابين شعبي؟","2:30":"لذلك يقول الرب إله إسرائيل: لقد وعدت أن يظل بيتك وبيت أبيك يخدمون في محضري إلى الأبد. أما الآن، يقول الرب: فحاشا لي أن أفعل ذلك، لأنني أكرم الذين يكرمونني، أما الذين يحتقرونني فيصغرون.","2:31":"ها هي أيام مقبلة يخطف فيها الموت رجالكم فلا يبقى شيخ في بيتك.","2:32":"وتشهد ضيقا في مسكني، بينما ينعم الإسرائيليون بالرفاهية ويخلو بيتك من الشيوخ كل الأيام.","2:33":"ويكون من أستحييه من ذريتك لخدمة مذبحي سببا في إعشاء عينيك بالدموع وإذابة قلبك بالحزن، وبقية ذريتك يموتون شبانا.","2:34":"وتصديقا لقولي أعطيك علامة تصيب ابنيك حفني وفينحاس: إنهما في يوم واحد يموتان كلاهما.","2:35":"فأختار لنفسي كاهنا مخلصا يعمل بمقتضى ما بقلبي ونفسي فأقيم له بيتا أمينا، ويصير كاهنا للملك الذي أختاره.","2:36":"وكل من يبقى من ذريتك يأتي إليه ساجدا متوسلا من أجل قطعة فضة ورغيف خبز، متضرعا إليه قائلا: هبني عملا بين الكهنة لآكل كسرة خبز».","3:1":"وخدم الصبي صموئيل الرب بإشراف عالي. وكانت رسائل الرب نادرة في تلك الأيام، والرؤى عزيزة.","3:2":"وحدث أن عالي كان مضطجعا في مكانه المعتاد وقد كل بصره فعجز عن النظر.","3:3":"وبينما كان صموئيل راقدا في هيكل الرب الذي فيه تابوت الله، ولم يكن سراج الله قد انطفأ بعد،","3:4":"دعا الرب صموئيل، فأجاب: «نعم».","3:5":"وهرول نحو عالي قائلا: «ها أنا قد جئت لأنك استدعيتني». فقال عالي: «إنني لم أدعك. عد واضطجع». فرجع صموئيل ورقد.","3:6":"ثم دعا الرب صموئيل مرة ثانية، فنهض صموئيل ومضى إلى عالي قائلا: «ها أنا جئت لأنك دعوتني». فأجابه: «إنني لم أدعك يا ابني، عد واضطجع».","3:7":"ولم يكن صموئيل قد عرف الرب بعد، ولا تلقى منه أية رسالة.","3:8":"ودعا الرب صموئيل مرة ثالثة، فقام وذهب إلى عالي قائلا: «ها أنا قد جئت لأنك دعوتني». فأدرك عالي آنئذ أن الرب هو الذي يدعو الصبي،","3:9":"فقال عالي لصموئيل: «اذهب وارقد، وإذا دعاك الرب فقل: تكلم يا رب لأن عبدك سامع». فذهب صموئيل ورقد في مكانه.","3:10":"ودعا الرب كما حدث في المرات السابقة: «صموئيل، صموئيل». فأجاب صموئيل: «تكلم لأن عبدك سامع»","3:11":"فقال الرب لصموئيل: «ها أنا مزمع أن أجري أمرا في إسرائيل تطن أذنا كل من يسمع به.","3:12":"إذ أوقع بعالي كل ما توعدت به بيته من أوله إلى آخره.","3:13":"وقد أنبأته بأنني سأدين بيته إلى الأبد، على الشر الذي يعلم أن ابنيه قد أوجبا به اللعنة على نفسيهما، فلم يردعهما.","3:14":"لهذا أقسمت أن لا يكفر عن إثم بيت عالي بذبيحة أو تقدمة إلى الأبد».","3:15":"ونام صموئيل إلى الصباح، ثم قام وفتح أبواب بيت الرب. وخاف أن يطلع عالي على الرؤيا.","3:16":"فاستدعى عالي إليه صموئيل.","3:17":"وسأله: «بماذا خاطبك الرب؟ لا تخف عني. ليضاعف الرب عقابك إن أخفيت عني كلمة مما خاطبك به الرب».","3:18":"فأطلعه صموئيل على جميع الكلام، ولم يخف عنه شيئا. فقال عالي: «إنه الرب، وهو يفعل ما يشاء».","3:19":"وكبر الصبي. وكان الرب معه. لم يخذله قط.","3:20":"وعرف جميع بني إسرائيل من دان إلى بئر سبع أن الرب قد ائتمن صموئيل ليكون له نبيا.","3:21":"وظل الرب يتجلى في شيلوه حيث كان يعلن ذاته لصموئيل من خلال رسائله التي كان صموئيل يبلغها لجميع الشعب.","4:1":"واحتشد الإسرائيليون عند حجر المعونة لمحاربة الفلسطينيين، وتجمع الفلسطينيون في أفيق.","4:2":"واصطف الفلسطينيون للقاء إسرائيل وما لبثت أن دارت رحى الحرب، فانهزم الإسرائيليون أمام الفلسطينيين الذين قتلوا منهم في ميدان المعركة نحو أربعة آلاف رجل.","4:3":"ورجع الناجون إلى معسكرهم، فتساءل شيوخ إسرائيل: «لماذا هزمنا الرب اليوم أمام الفلسطينيين؟ لنأت بتابوت عهد الرب من شيلوه وندخله في وسطنا فينقذنا من قبضة أعدائنا».","4:4":"فبعث الجيش إلى شيلوه بمن حمل تابوت عهد الرب القدير الجالس على الكروبيم، ورافقه أيضا ابنا عالي: حفني وفينحاس.","4:5":"وما إن دخل تابوت عهد الرب إلى المعسكر حتى هتف جميع الجيش هتافا عظيما ارتجت له الأرض.","4:6":"فسمع الفلسطينيون ضجيج الهتاف فتساءلوا: «ما ضجيج الهتاف هذا في معسكر العبرانيين؟» ولما عرفوا أن تابوت الرب قد جيء به إلى المعسكر،","4:7":"اعتراهم الخوف وقالوا: «لقد جاء الله إلى المعسكر، فالويل لنا لأنه لم يحدث مثل هذا من قبل.","4:8":"ويل لنا! من ينقذنا من يد أولئك الآلهة القادرين، فإنهم هم الآلهة الذين أنزلوا بمصر كل صنوف الضربات في البرية.","4:9":"تشجعوا، وكونوا أبطالا أيها الفلسطينيون، لئلا يستعبدكم العبرانيون كما استعبدتموهم. كونوا رجالا واستبسلوا في القتال».","4:10":"فحارب الفلسطينيون وانهزم الإسرائيليون، وفر كل واحد إلى خيمته. وكانت المجزرة عظيمة جدا، وقتل من إسرائيل ثلاثون ألف رجل.","4:11":"واستولى الفلسطينيون على تابوت الله، ومات ابنا عالي حفني وفينحاس.","4:12":"وأقبل في ذلك اليوم رجل من ميدان المعركة إلى شيلوه بثياب ممزقة ورأس معفر بالتراب.","4:13":"وكان عالي حينذاك جالسا على كرسي إلى جوار الطريق يراقب، لأن قلبه كان مضطربا على مصير تابوت الله. وما إن دخل الرجل المدينة وأذاع النبأ حتى ضجت المدينة كلها بالصراخ.","4:14":"فتساءل عالي: «ما سر هذا الضجيج؟» فأسرع الرجل يبلغه الخبر.","4:15":"وكان عالي قد بلغ من العمر ثمان وتسعين سنة، وكانت عيناه قد كلتا جدا، فلم يعد قادرا على الإبصار.","4:16":"فقال الرجل: «لقد وصلت لتوي من ميدان القتال هاربا اليوم من لهيب المعركة». فسأله: «ماذا جرى يا بني؟»","4:17":"فأجاب: «انهزم الإسرائيليون أمام الفلسطينيين، وقتل عدد كبير جدا من الجيش، ومات أيضا هناك ابناك حفني وفينحاس، وأخذ تابوت الله».","4:18":"وما إن ذكر الرجل نبأ تابوت الله حتى سقط عالي عن الكرسي إلى الوراء إلى جوار الباب، فانكسرت رقبته ومات لأنه كان رجلا شيخا ثقيل الجسم. وقد قضى لبني إسرائيل مدة أربعين سنة.","4:19":"وكانت كنته امرأة فينحاس حبلى توشك على الولادة، فلما بلغها خبر الاستيلاء على تابوت الله ووفاة حميها ومقتل زوجها، سقطت وولدت، لأن آلام المخاض هاجمتها.","4:20":"وعند احتضارها قالت لها النسوة المحيطات بها: «لا تجزعي، فقد رزقت بولد»؛ فلم تجب ولم يأبه قلبها للبشرى.","4:21":"ودعت الصبي إيخابود قائلة: «قد زال المجد من إسرائيل»؛ لأن تابوت الله قد أخذ ومات حموها وزوجها","4:22":"وهذا ما دعاها للقول: «قد زال المجد من إسرائيل لأن تابوت الله قد أخذ».","5:1":"وأخد الفلسطينيون تابوت الله ونقلوه من حجر المعونة إلى أشدود،","5:2":"ثم أدخلوه إلى معبد داجون إلههم، ووضعوه إلى جواره.","5:3":"وفي صباح اليوم التالي وجد أهل أشدود صنم إلههم داجون مطروحا على وجهه إلى الأرض أمام تابوت الرب، فرفعوه وأقاموه في موضعه.","5:4":"وفي صباح اليوم التالي عثروا على صنم داجون مطروحا على وجهه إلى الأرض أمام تابوت الرب، ورأسه ويداه مقطوعة وملقاة على العتبة، ولم يبق منه سوى جسم السمكة.","5:5":"لذلك لا يطأ كهنة داجون وسائر الداخلين إلى معبد داجون على عتبة المعبد في أشدود إلى هذا اليوم.","5:6":"ثم ثقلت وطأة الرب على الأشدوديين والقرى المحيطة بهم، فأصابهم الخراب، وبلاهم بالبواسير.","5:7":"وعندما تبين أهل أشدود ما يجري قالوا: «لا ينبغي أن يمكث تابوت إله إسرائيل عندنا، لأن وطأة يده قد قست علينا وعلى داجون إلهنا».","5:8":"فاستدعوا أقطاب الفلسطينيين جميعهم قائلين: «ماذا نصنع بتابوت إله إسرائيل؟» فأجابوهم: «انقلوه إلى جت». وعندما نقلوا تابوت إله إسرائيل إلى جت،","5:9":"عاقبت يد الرب المدينة، فأصاب أهلها اضطراب عظيم جدا، وتفشى في صغيرهم وكبيرهم داء البواسير.","5:10":"فأرسلوا تابوت الله إلى عقرون. وما إن دخل المدينة حتى صرخ أهل عقرون قائلين: «قد نقلوا إلينا تابوت إله إسرائيل لكي يقضوا علينا وعلى شعبنا».","5:11":"فبعثوا واستدعوا أقطاب الفلسطينيين وقالوا: «أعيدوا تابوت إله إسرائيل فيرجع إلى موضعه ولا يفنينا نحن وشعبنا»؛ لأن الموت قد ملأ المدينة بالرعب، إذ صارت وطأة يد الرب عليهم ثقيلة جدا،","5:12":"ومن لم يمت من الناس تفشت فيهم البواسير، فارتفع صراخ المدينة إلى عنان السماء.","6:1":"وبقي تابوت الله في بلاد الفلسطينيين سبعة أشهر.","6:2":"ثم سأل الفلسطينيون الكهنة والعرافين: «ماذا نفعل بتابوت الرب؟ أخبرونا كيف نعيده إلى موطنه».","6:3":"فأجابوهم: «إذا أعدتم تابوت إله إسرائيل فلا تعيدوه فارغا بل أرسلوا معه قربان إثم، حينئذ تبرأون وتدركون علة ما أصابكم من عقاب».","6:4":"فسألوهم: «وما هو قربان الإثم الذي نرسله؟» فأجابوا: «أرسلوا بحسب عدد أقطاب الفلسطينيين خمسة نماذج ذهبية للبواسير، وخمسة نماذج ذهبية للفئران، لأن الكارثة التي ابتليتم بها واحدة عليكم وعلى أقطابكم.","6:5":"واسبكوا نماذج بواسيركم ونماذج فيرانكم التي خربت الأرض، ومجدوا إله إسرائيل، لعله يخفف من وطأة يده عنكم وعن آلهتكم وعن أرضكم.","6:6":"فلماذا تصلبون قلوبكم كما صلب المصريون وفرعون قلوبهم؟ ألم يطلقوهم على أثر ما أوقع بهم من عقاب؟","6:7":"والآن اصنعوا عربة واحدة جديدة واربطوها إلى بقرتين مرضعتين لم يعلهما نير، وردوا عجليهما عنهما إلى الحظيرة،","6:8":"ثم ضعوا تابوت الرب على العربة مع صندوق فيه أمتعة الذهب التي تردونها له لتكون قربان إثم، وأطلقوا العربة بما عليها فتذهب.","6:9":"وراقبوها، فإن اتجهت في طريق أرض إسرائيل إلى بيت شمس تعلمون آنئذ أن إله إسرائيل هو الذي أنزل بنا هذا الشر العظيم، وإن مضت في غير هذا الاتجاه، ندرك أن ما أصابنا هو صدفة، ولم يكن عقابا من يده».","6:10":"فنفذ الرجال الأمر، وأخذوا بقرتين مرضعتين ربطوهما إلى العربة وحبسوا عجليهما في الحظيرة،","6:11":"ثم وضعوا تابوت الرب على العربة مع الصندوق وفيران الذهب ونماذج بواسيرهم،","6:12":"فاتجهت البقرتان وهما تجأران، مباشرة في طريق بيت شمس في خط مستقيم، لا تحيدان يمينا ولا شمالا. وسار أقطاب الفلسطينيين خلفهما حتى حدود بيت شمس.","6:13":"وكان أهل بيت شمس يقومون بحصاد القمح في الوادي، وما إن رأوا التابوت حتى غمرت البهجة قلوبهم","6:14":"وتوجهت العربة إلى حقل رجل اسمه يهوشع البيتشمسي، ووقفت بجوار حجر كبير. فشق أهل بيت شمس خشب العربة وذبحوا البقرتين وقدموهما محرقة للرب.","6:15":"وأنزل بعض اللاويين تابوت الرب والصندوق الذي معه، بما فيه من أمتعة الذهب، وأقاموهما على الحجر الكبير. في ذلك اليوم أصعد أهل بيت شمس محرقات وقربوا ذبائح للرب.","6:16":"وبعد أن شاهد أقطاب الفلسطينيين الخمسة ما جرى رجعوا إلى عقرون في اليوم نفسه.","6:17":"أما قرابين الإثم للرب التي ردها الفلسطينيون من نماذج بواسير الذهب، فكانت واحدا عن أشدود، وواحدا عن غزة، وواحدا عن أشقلون، وواحدا عن جت، وواحدا عن عقرون.","6:18":"وكانت نماذج فيران الذهب على عدد مدن أقطاب الفلسطينيين الخمسة، سواء كانت مدنا محصنة أم قرية في الصحراء. ولا يزال الحجر الكبير الذي وضعوا تابوت الرب عليه باقيا حتى الآن في حقل يهوشع في بيت شمس، شاهدا على هذا.","6:19":"وعاقب الرب أهل بيت شمس فقتل منهم سبعين رجلا لأنهم نظروا إلى ما بداخل تابوت الرب، فناح الشعب لأن الرب أوقع بهم كارثة عظيمة.","6:20":"وقال أهل بيت شمس: «من يستطيع أن يقاوم الرب الإله القدوس هذا؟ وإلى أين نرسل التابوت من هنا؟»","6:21":"وبعثوا برسل إلى أهل قرية يعاريم قائلين: «قد أعاد الفلسطينيون تابوت الرب، فتعالوا وخذوه».","7:1":"وجاء أهل يعاريم وأخذوا تابوت الرب حيث وضعوه في بيت أبيناداب القائم على التل، وكرسوا ألعازار ابنه ليقوم على حراسة التابوت.","7:2":"وطالت مدة بقاء التابوت في قرية يعاريم، إذ انقضت عشرون سنة عليه هناك. تاب فيها كل بني إسرائيل إلى الرب نائحين.","7:3":"فقال صموئيل لكل شعب إسرائيل: «إن كنتم حقا قد تبتم من كل قلوبكم إلى الرب، فانزعوا الآلهة الغريبة وأصنام العشتاروث من وسطكم، وهيئوا قلوبكم للرب واعبدوه وحده، فينقذكم من قبضة الفلسطينيين».","7:4":"فتخلص بنو إسرائيل من البعليم وأصنام عشتاروث، وعبدوا الرب وحده.","7:5":"فقال صموئيل: «ادعوا كل إسرائيل للاجتماع في المصفاة فأصلي لأجلكم إلى الرب».","7:6":"فاجتمعوا في المصفاة حيث استقوا ماء وسكبوه أمام الرب، وصاموا في ذلك اليوم قائلين هناك: «قد أخطأنا إلى الرب». وكان صموئيل يقضي لبني إسرائيل في المصفاة.","7:7":"وإذ سمع أقطاب الفلسطينيين بتجمع الإسرائيليين في المصفاة، احتشدوا لمحاربتهم. وعندما بلغ الخبر بني إسرائيل اعتراهم الخوف من الفلسطينيين،","7:8":"وقالوا لصموئيل: «لا تكف عن التضرع إلى الرب إلهنا من أجلنا حتى يخلصنا من قبضة الفلسطينيين».","7:9":"فأخذ صموئيل حملا رضيعا، وقدمه بكامله محرقة للرب، وتضرع إليه من أجل إنقاذ إسرائيل، فاستجاب له الرب.","7:10":"وبينما كان صموئيل يقدم المحرقة، أقبل الفلسطينيون لمحاربة إسرائيل، فأطلق الرب صرخة راعدة عظيمة على الفلسطينيين ألقت فيهم الرعب فانهزموا أمام إسرائيل.","7:11":"فاندفع رجال إسرائيل من المصفاة، وتعقبوهم إلى ما تحت بيت كار، وقضوا عليهم.","7:12":"فأخذ صموئيل حجرا ونصبه بين المصفاة والسن، ودعاه «حجر المعونة» وقال: «إلى هنا أعاننا الرب»","7:13":"فانكسرت شوكة الفلسطينيين ولم يجرؤوا على التعدي على تخوم إسرائيل، لأن يد الرب كانت ضد الفلسطينيين طوال حياة صموئيل.","7:14":"واسترد بنو إسرائيل كل المدن التي اقتطعها الفلسطينيون منهم من عقرون إلى جت، واستعادوا تخومهم من يد الفلسطينيين. كما عقد بنو إسرائيل معاهدة صلح مع الأموريين.","7:15":"وظل صموئيل قاضيا لإسرائيل كل أيام حياته،","7:16":"فكان في كل سنة ينتقل بين بيت إيل والجلجال والمصفاة ليعقد مجلس قضائه فيها،","7:17":"ثم يرجع للرامة حيث يقيم، وهناك يقضي لإسرائيل، كما بنى هناك مذبحا للرب.","8:1":"ولما طعن صموئيل في السن نصب ابنيه قاضيين لإسرائيل.","8:2":"وكان اسم ابنه البكر يوئيل، واسم الثاني أبيا، وكان مقر قضائهما في بئر سبع.","8:3":"غير أنهما لم يسلكا في طريقه، بل غويا وراء المكسب وقبلا الرشوة وحابيا في القضاء.","8:4":"فاجتمع شيوخ إسرائيل وجاءوا إلى صموئيل في الرامة،","8:5":"وقالوا له: «ها أنت قد شخت، ولم يسلك ابناك في طريقك، فنصب علينا ملكا يحكم علينا كبقية الشعوب».","8:6":"فاستاء صموئيل من طلبهم تنصيب ملك عليهم ليحكم بينهم، وصلى إلى الرب،","8:7":"فقال الرب له: «لب للشعب طلبه وانزل عند رغبتهم، لأنهم لم يرفضوك أنت بل إياي رفضوا، لكي لا أملك عليهم.","8:8":"وهم يعاملونك الآن كما عاملوني منذ أن أصعدتهم من ديار مصر إلى هذا اليوم، إذ تركوني وعبدوا آلهة أخرى.","8:9":"والآن لب طلبهم، إنما أشهد عليهم وحذرهم مما يجريه الملك المتسلط عليهم من قضاء».","8:10":"وأبلغ صموئيل الشعب بكل ما قاله الرب،","8:11":"وقال: «اسمعوا، هذا ما يقضي به الملك الذي سيحكم عليكم: يجند أبناءكم ويجعلهم فرسانا وخداما وجنودا يركضون أمام مركباته","8:12":"ويعين بعضهم قادة ألوف وقادة خماسين، يحرثون حقوله ويحصدون غلاته، ويصنعون أسلحته ومركباته الحربية.","8:13":"ويأخذ من بناتكم ليجعل منهن طباخات وخبازات وصانعات عطور،","8:14":"ويستولي على أجود حقولكم وكرومكم وزيتونكم ويهبها لعبيده.","8:15":"ويجني عشر محاصيلكم ليوزعها على أصدقائه وحاشيته","8:16":"ويسخر عبيدكم وجواريكم وخيرة شبانكم وحميركم في أعماله.","8:17":"ويستولي على عشر غنمكم ويستعبدكم.","8:18":"فتستغيثون في ذلك اليوم من جور ملككم، الذي اخترتموه لأنفسكم، فلا يستجيب لكم الرب».","8:19":"ولكن الشعب أبى أن يستمع لتحذيرات صموئيل، وأصر قائلا: «لا بل نصب علينا ملكا،","8:20":"فنكون كسائر الشعوب، لنا ملك يقضي بيننا ويقودنا ويحارب معاركنا».","8:21":"فسمع صموئيل لكلام الشعب، وردده أمام الرب،","8:22":"فقال الرب لصموئيل: «لب طلبهم ونصب عليهم ملكا». فقال صموئيل لرجال إسرائيل: «لينصرف كل واحد منكم إلى مدينته».","9:1":"وكان رجل من سبط بنيامين من ذوي النفوذ يدعى قيس بن أبيئيل بن صرور بن بكورة بن أفيح،","9:2":"وكان له ابن اسمه شاول من أكثر شبان إسرائيل وسامة وأكثرهم طولا، لم يزد طول قامة أحد من الشعب عن ارتفاع كتفيه.","9:3":"وحدث أن ضلت حمير قيس أبي شاول، فقال له: «خذ معك واحدا من الغلمان وامض باحثا عن الحمير».","9:4":"فراح يبحث عنها في جبل أفرايم وفي أرض شليشة، فلم يعثر عليها. فاجتاز مع غلامه إلى أرض شعليم، ثم إلى أرض بنيامين فلم يجدا لها أثرا.","9:5":"وعندما بلغا أرض صوف قال شاول لرفيقه الغلام: «تعال نرجع لئلا يقلق أبي علينا أكثر من قلقه على الحمير».","9:6":"فأجابه: «في هذه المدينة يقيم نبي يتمتع بالإكرام، وكل ما ينبئ به يتحقق، فلنذهب إليه لعله يخبرنا عن الطريق التي علينا سلوكها».","9:7":"فقال شاول للغلام: «كيف نذهب إليه ونحن لا نحمل معنا هدية نقدمها إليه حتى الخبز الذي كان معنا قد نفد. إننا لا نملك شيئا».","9:8":"فقال الغلام: «معي ربع شاقل (أي ثلاثة جرامات) من الفضة، نقدمها له فيخبرنا عن الطريق التي نتخذها».","9:9":"وكان النبي حينذاك يدعى الرائي، فكان الرجل يقول عند ذهابه ليستشير الرب: «هيا نذهب إلى الرائي»","9:10":"فقال شاول لغلامه: «حسنا ما تقول. هلم نذهب». وانطلقا إلى المدينة التي فيها رجل الله.","9:11":"وعندما بلغا مشارف المدينة صادفا فتيات خارجات لاستقاء الماء، فسألاهن: «أهنا الرائي؟»","9:12":"فأجبنهما: «نعم. ها هو أمامكما. أسرعا الآن لأنه قدم اليوم إلى المدينة لأن الشعب يقرب اليوم ذبيحة على التل.","9:13":"فإن دخلتما المدينة على التو، تلحقان به قبل صعوده إلى التل ليأكل، لأن الشعب لا يأكل من الذبيحة حتى يأتي ويباركها. بعد ذلك يتناول المدعوون منها. فأسرعا الآن خلفه إن شئتما اليوم لقاءه».","9:14":"فتوجها نحو المدينة. وفيما هما يجتازان في وسطها، إذا بصموئيل مقبل للقائهما في طريق صعوده إلى التل.","9:15":"وكان الرب قد أعلن لصموئيل في اليوم السابق لحضور شاول:","9:16":"«غدا في مثل هذا الوقت أبعث إليك رجلا من أرض بنيامين. فامسحه حاكما على شعبي إسرائيل، فيخلصهم من قبضة الفلسطينيين، فقد رق قلبي لشعبي، لأن استغاثتهم قد ارتفعت إلي».","9:17":"فما إن شاهد صموئيل شاول حتى قال له الرب: «ها هو الرجل الذي أخبرتك عنه. هذا الذي يحكم شعبي».","9:18":"وتقدم شاول إلى صموئيل وقال: «أخبرني، أين بيت الرائي؟»","9:19":"فأجاب صموئيل: «أنا هو الرائي. اصعد أمامي إلى التل حيث نتناول الطعام معا، ثم أطلقك صباحا بعد أن أخبرك بكل ما تود معرفته.","9:20":"أما الحمير التي ضلت منذ ثلاثة أيام فلا تقلق بشأنها، لأنه قد تم العثور عليها. أليس كل نفيس في إسرائيل، هو لك ولكل بيت أبيك؟»","9:21":"فأجاب شاول: «يا سيدي، أنا أنتمي لسبط بنيامين، أصغر أسباط إسرائيل، وعشيرتي أصغر عشائر بنيامين شأنا، فلماذا تحدثني بمثل هذا الكلام؟»","9:22":"فأخذ صموئيل شاول وغلامه وأدخلهما إلى قاعة الطعام، وأجلسهما على رأس المائدة التي التف حولها نحو ثلاثين رجلا،","9:23":"وقال للطباخ: «أحضر قطعة اللحم التي أعطيتك إياها وطلبت منك أن تحتفظ بها عندك».","9:24":"فتناول الطباخ الساق وما عليها ووضعها أمام شاول، وقال صموئيل: «هذا ما احتفظت به لك. كل منه لأنه قد احتفظ به خصيصا لك منذ أن قلت: إنني دعوت ضيوفا». فأكل شاول مع صموئيل في ذلك اليوم.","9:25":"وعندما انحدروا من التل إلى المدينة تحادث صموئيل وشاول على السطح.","9:26":"وفي فجر اليوم التالي استدعى صموئيل شاول ليصعد إلى سطح البيت قائلا: «انهض لأصرفك». فتهيأ شاول للانصراف، وشيعه صموئيل إلى الخارج.","9:27":"وعندما بلغا طرف المدينة قال صموئيل لشاول: «قل للغلام أن يسبقنا». وعندما سبقهما قال صموئيل لشاول: «قف لأتلو عليك رسالة الله لك».","10:1":"وأخذ صموئيل قنينة زيت وصب على رأس شاول وقبله وقال: «لقد مسحك الرب رئيسا على ميراثه.","10:2":"حالما تنصرف من عندي اليوم تصادف رجلين بالقرب من قبر راحيل في صلصح في أرض بنيامين، فيقولان لك: قد تم العثور على الحمير التي ذهبت تبحث عنها، وقد تبدد قلق أبيك بشأنها. إلا أن القلق استبد به عليكما قائلا: كيف يمكن أن أعثر على ولدي؟","10:3":"وتتابع سيرك من هناك حتى تصل إلى بلوطة تابور، فيلتقيك هناك ثلاثة رجال في طريقهم إلى بيت إيل ليقدموا قربانا لله، يحمل أحدهم ثلاثة جداء، ويحمل الثاني ثلاثة أرغفة خبز، ويحمل الثالث زق خمر،","10:4":"فيحيونك ويقدمون لك رغيفي خبز، فاقبلهما منهم.","10:5":"بعد ذلك تصل إلى تل الله في جبعة حيث تعسكر حامية للفلسطينيين. فتصادفك عند مدخل جبعة مجموعة من الأنبياء نازلين من التل يعزفون على الرباب والدف والناي والعود وهم يتنبأون،","10:6":"فيحل عليك روح الرب فتتنبأ معهم وتصير رجلا آخر.","10:7":"وعندما تتحقق هذه العلامات لك، فافعل ما تراه موافقا، لأن الرب معك.","10:8":"وعليك أن تسبقني إلى الجلجال لأنني قادم إليها لأصعد للرب محرقات وأقرب ذبائح سلام، فامكث هناك سبعة أيام ريثما آتي إليك لأطلعك عما يتوجب عليك عمله».","10:9":"وما إن انصرف من عند صموئيل، وبدأ رحلة عودته حتى أنعم الله عليه بقلب جديد وتحققت له جميع تلك العلامات.","10:10":"وعندما وصل جبعة قابلته مجموعة من الأنبياء، فحل عليه روح الله وتنبأ في وسطهم.","10:11":"وحين شاهده الذين كانوا يعرفونه من قبل يتنبأ، تساءلوا فيما بينهم: «ماذا جرى لابن قيس؟ أشاول أيضا بين الأنبياء؟»","10:12":"فأجاب رجل من المقيمين هناك: «ومن هو أبو الأنبياء؟» وهكذا صار القول: «أشاول أيضا بين الأنبياء» مثلا.","10:13":"ولما فرغ من التنبوء، صعد إلى المرتفع،","10:14":"فرآه عمه، ورأى غلامه، فسألهما: «إلى أين ذهبتما؟» فأجابه: «للبحث عن الحمير، ولما أخفقنا في العثور عليها قدمنا إلى صموئيل».","10:15":"فقال عم شاول: «أنبئني ماذا قال لكما صموئيل؟»","10:16":"فأجاب شاول عمه: «أعلمنا أن الحمير قد تم العثور عليها». ولكنه كتم عنه أمر المملكة الذي حدثه به صموئيل.","10:17":"واستدعى صموئيل الشعب للاجتماع إلى الرب في المصفاة.","10:18":"وأبلغهم رسالة الرب لهم، التي تقول: «إني قد أخرجت إسرائيل من مصر وأنقذتكم من قبضة المصريين ومن جور الممالك الأخرى التي ضايقتكم،","10:19":"ولكنكم اليوم تنكرتم لإلهكم، مخلصكم من جميع المسيئين إليكم ومن مضايقيكم، وقلتم له: نصب علينا ملكا. والآن امثلوا أمام الرب حسب أسباطكم وعشائركم».","10:20":"وطلب صموئيل من كل سبط أن يتقدم بدوره للمثول أمام الرب، فاختار الرب سبط بنيامين.","10:21":"ثم تقدمت عشائر سبط بنيامين، فاختار الرب عشيرة مطري، ومنها وقع الاختيار على شاول بن قيس. فبحثوا عنه فلم يعثروا عليه.","10:22":"فسألوا الرب: «ألم يأت الرجل إلى هنا بعد؟» فأجاب: «هوذا قد اختبأ بين الأمتعة».","10:23":"فتراكضوا وأحضروه من هناك. فوقف بين الشعب، فكان أطولهم قامة من كتفيه فما فوق.","10:24":"فقال صموئيل لجميع الشعب: «أشاهدتم من اختاره الرب ليكون ملكا عليكم؟ ليس له نظير في كل الشعب»؛ فهتفوا: «ليحي الملك!»","10:25":"وأطلع صموئيل الشعب على حقوق الملك وواجباته ودونها في كتاب ووضعه أمام الرب. ثم صرف صموئيل جميع الشعب إلى بيوتهم.","10:26":"ومضى شاول أيضا إلى بيته إلى جبعة ترافقه الجماعة التي مس الله قلبها.","10:27":"غير أن فئة من الغوغاء قالوا: «كيف ينقذنا هذا؟» فاحتقروه ولم يقدموا له هدايا. أما شاول فاعتصم بالصمت.","11:1":"وزحف ناحاش العموني على يابيش جلعاد وحاصرها، فقال أهل يابيش لناحاش: «وقع معنا معاهدة فنصبح عبيدا لك»","11:2":"فأجابهم: «حسنا، ولكن بشرط أن أقلع العين اليمنى لكل واحد منكم، فيصبح ذلك عارا على كل إسرائيل».","11:3":"فقال له زعماء يابيش: «أمهلنا سبعة أيام، نبعث فيها رسلا إلى جميع أراضي إسرائيل طالبين النجدة، فإن لم يغثنا أحد، نذعن لشرطك».","11:4":"وعندما وصل رسل يابيش إلى جبعة شاول، وأطلعوا الشعب على الأمر، علا بكاء الشعب.","11:5":"وفيما هم كذلك، أقبل شاول من الحقل يقود أمامه البقر، فتساءل: «ما بال الشعب يبكي؟» فرووا له خبر أهل يابيش،","11:6":"فحل عليه روح الله عندما سمع الخبر وثار غضبه.","11:7":"وأخذ ثورين قطعهما إلى أجزاء وزعها على كل أرجاء إسرائيل بيد رسل قائلا: «هكذا يحدث لبقر كل من يتخلف عن الخروج وراء شاول ووراء صموئيل». فطغى رعب الرب على قلوبهم، والتفوا حول شاول كرجل واحد.","11:8":"وأحصاهم شاول في بازق فبلغ عددهم ثلاث مئة ألف، فضلا عن ثلاثين ألفا من رجال يهوذا.","11:9":"وقالوا للرسل الوافدين: «أخبروا أهل يابيش أن غدا، عند اشتداد حر الشمس، يتم خلاصكم». وعندما عاد الرسل وأخبروا أهل يابيش عمهم الفرح.","11:10":"فقال أهل يابيش للعمونيين: «غدا نخرج إليكم مستسلمين لتصنعوا بنا ما يطيب لكم».","11:11":"وفي صباح اليوم التالي قسم شاول جيشه إلى ثلاث فرق، وهجموا على معسكر العمونيين عند الفجر وأعملوا فيهم تقتيلا حتى اشتد حر النهار. والذين نجوا منهم تشتتوا حتى لم يبق منهم اثنان معا.","11:12":"وقال بنو إسرائيل: «أين هؤلاء الذين تساءلوا: أيملك شاول علينا؟ سلموهم لنا فنقتلهم».","11:13":"فقال شاول: «لا يقتل أحد في هذا اليوم، لأن الرب قد صنع اليوم خلاصا في إسرائيل».","11:14":"وقال صموئيل للشعب: «هيا نذهب إلى الجلجال لنجدد هناك عهد الملك».","11:15":"فتوجه الشعب إلى الجلجال، وملكوا هناك شاول أمام الرب، وقربوا ذبائح سلام في حضرة الرب. وغمرت الفرحة شاول وسائر رجال إسرائيل.","12:1":"وقال صموئيل لكل الإسرائيليين: «ها أنا قد لبيت طلبكم وحققت لكم كل ما سألتم ونصبت عليكم ملكا،","12:2":"وقد صار لكم ملك يسير أمامكم، وأما أنا فقد شخت وغزا الشيب شعر رأسي. وها أولادي بينكم، وأنا قد خدمتكم منذ صباي.","12:3":"فاشهدوا علي في حضرة الرب، وأمام ملكه المختار، إن كنت قد أخذت ثورا أو حمارا من أحد، أو ظلمت أو جرت على أحد أو قبلت رشوة من أحد لأغمض عيني عنه، فأعوض ذلك عليكم».","12:4":"فأجابوه: «لم تظلمنا ولم تجر علينا ولا أخذت شيئا من أحد».","12:5":"فقال لهم: «ليكن الرب وملكه المختار شاهدين في هذا اليوم على براءتي الكاملة». فقالوا: «يشهد الرب».","12:6":"وقال صموئيل للشعب: «إن الرب هو الذي اختار موسى وهرون وأخرج آباءكم من ديار مصر.","12:7":"والآن امثلوا أمام الرب لأذكركم بجميع معاملاته التي أجراها معكم ومع آبائكم:","12:8":"بعد أن نزل يعقوب ديار مصر، واضطهد المصريون ذريته، استغاث آباؤكم بالرب، فأرسل إليهم موسى وهرون فأخرجاهم من ديار مصر وقاداهم للإقامة في هذا الموضع.","12:9":"وعندما تناسوا الرب إلههم سلط عليهم سيسرا قائد جيش حاصور والفلسطينيين، وملك موآب فحاربوهم.","12:10":"فاستغاثوا بالرب قائلين: أخطأنا إذ تركنا الرب وعبدنا البعليم والعشتاروث. فالآن أنقذنا من قبضة أعدائنا فنخلص لك العبادة.","12:11":"فأقام الرب جدعون وبدان ويفتاح وصموئيل وأنقذكم من قبضة أعدائكم المحيطين بكم، وسكنتم مطمئنين.","12:12":"ولما عاينتم ناحاش ملك عمون زاحفا عليكم قلتم لي: نصب علينا ملكا، مع أن الرب إلهكم هو ملككم.","12:13":"والآن ها هو الرجل الذي اخترتم وطلبتم، قد جعله الرب عليكم ملكا.","12:14":"فإن اتقيتم الرب وعبدتموه وأطعتم وصاياه ولم تعصوا أمره واتبعتم الرب إلهكم أنتم وملككم المتسلط عليكم: فلن يصيبكم مكروه.","12:15":"ولكن إن عصيتم وصايا الرب وأمره، فإن عقاب الرب ينزل بكم كما نزل بآبائكم.","12:16":"والآن قفوا وانظروا ما يجريه الرب من آية عظيمة أمامكم:","12:17":"أليس اليوم هو موسم حصاد القمح؟ سأصلي إلى الرب حتى يرسل عليكم رعودا ومطرا، فتدركون عظم الشر الذي ارتكبتموه في عيني الرب حين طلبتم أن ينصب عليكم ملكا».","12:18":"وصلى صموئيل إلى الرب فأرسل رعودا ومطرا في ذلك اليوم، فاستولى خوف شديد على الشعب من الرب ومن صموئيل.","12:19":"وتوسل جميع الشعب إلى صموئيل قائلين: «صل من أجل عبيدك إلى الرب إلهك لكي لا نموت، لأننا قد أضفنا إلى جميع خطايانا شرا جديدا حين طلبنا أن ينصب علينا ملكا».","12:20":"فقال صموئيل للشعب: «لا تخافوا، فأنتم حقا قد اقترفتم كل هذا الشر، ولكن إياكم أن تحيدوا عن الرب، بل اعبدوه من كل قلوبكم.","12:21":"ولا تضلوا وراء الأصنام الباطلة التي لا تفيد ولا تنقذ، لأنه لا طائل منها.","12:22":"فالرب لا يتخلى عن شعبه إكراما لاسمه العظيم، لأنه شاء أن يجعلكم له شعبا.","12:23":"وأما أنا فحاشا لي أن أخطىء إلى الرب، فأكف عن الصلاة من أجلكم، بل أواظب على تعليمكم الطريق الصالح المستقيم.","12:24":"وعليكم بتقوى الرب وعبادته بأمانة من كل قلوبكم، متأملين العظائم التي صنعها معكم.","12:25":"وأما إن ارتكبتم الشر فمصيركم أنتم وملككم الهلاك».","13:1":"كان شاول ابن (ثلاثين) سنة حين ملك، وفي السنة الثانية من ملكه،","13:2":"اختار ثلاثة آلاف رجل من إسرائيل، احتفظ بألفين منهم لنفسه في مخماس وفي جبل بيت إيل، وترك ألفا مع يوناثان ابنه في جبعة بنيامين. وأما بقية الجيش فقد سرحهم ليعود كل إلى بيته.","13:3":"وهاجم يوناثان حامية الفلسطينيين المعسكرة في جبع، فبلغ الخبر الفلسطينيين. وأطلق شاول البوق في كل الأرض قائلا: «ليسمع جميع العبرانيين».","13:4":"فذاع نبأ أن شاول هاجم حامية الفلسطينيين، وأن الفلسطينيين عازمون على الانتقام من الإسرائيليين، فتحرك جيش إسرائيل كله ولحق بشاول في الجلجال.","13:5":"واحتشد الفلسطينيون لمحاربة إسرائيل بقوة تتألف من ثلاثين ألف مركبة حربية، وستة آلاف فارس وجيش كرمل شاطىء البحر في كثرته، وتجمعوا في مخماس شرقي بيت آون.","13:6":"وعندما رأى بنو إسرائيل حرج موقفهم اعتراهم الضيق، فاختبأوا في المغاور والأدغال وبين الصخور والأبراج والآبار.","13:7":"واجتاز بعض العبرانيين نهر الأردن إلى أرض جاد وجلعاد. أما شاول فظل في الجلجال مع بقية من الجيش ملأ قلوبها الذعر.","13:8":"ومكث شاول سبعة أيام في الجلجال ينتظر مجيء صموئيل بموجب اتفاق سابق. وعندما تأخر صموئيل عن الحضور وتفرق الجيش عن شاول،","13:9":"قال شاول: «قدموا إلي المحرقة وذبائح السلام». وقرب المحرقة.","13:10":"وما إن انتهى من تقديمها حتى أقبل صموئيل، فخرج شاول للقائه ليتلقى بركته.","13:11":"فسأل صموئيل: «ماذا فعلت؟» فأجابه شاول: «رأيت أن الشعب تفرق عني، وأنت لم تحضر في موعدك، والفلسطينيون محتشدون في مخماس،","13:12":"فقلت إن الفلسطينيين متأهبون الآن للهجوم علي في الجلجال وأنا لم أتضرع إلى الرب بعد طلبا لعونه، فوجدت نفسي مرغما على تقريب المحرقة».","13:13":"فقال صموئيل لشاول: «لقد تصرفت بحماقة، فأنت قد عصيت وصية الرب إلهك التي أمرك بها. ولو أطعته لثبت ملكك على إسرائيل إلى الأبد.","13:14":"أما الآن، فلأنك لم تطع ما أمرك الرب به فإن ملكك لن يدوم، لأن الرب قد اختار لنفسه رجلا حسب قلبه وأمره أن يصبح رئيسا على شعبه».","13:15":"وانطلق صموئيل من الجلجال إلى جبعة بنيامين. وأحصى شاول من بقي معه من الجيش وإذا بهم نحو ست مئة رجل.","13:16":"وكان شاول وابنه يوناثان ومن معهما من الجيش معسكرين في جبع بنيامين، أما الفلسطينيون فكانوا متجمعين في مخماس.","13:17":"وخرجت ثلاث فرق غزاة من معسكر الفلسطينيين توجهت إحداها في طريق عفرة إلى أرض شوعال،","13:18":"وانطلقت الفرقة الثانية في طريق بيت حورون. أما الفرقة الثالثة فقد اتجهت في طريق الحدود المشرفة على وادي صبوعيم نحو الصحراء.","13:19":"ولم يسمح الفلسطينيون في تلك الأيام بوجود حدادين في كل أرض إسرائيل لئلا يصنع العبرانيون سيوفا ورماحا.","13:20":"فكان على الإسرائيليين أن يلجأوا إلى أرض الفلسطينيين ليسنوا رؤوس محاريثهم ومناجلهم وفؤوسهم ومعاولهم.","13:21":"فكانت أجرة سن المحراث والمنجل ثلثي شاقل (نحو ثمانية جرامات من الفضة) ولكل مثلثات الأسنان والفؤوس والمناخس ثلث شاقل (أي أربعة جرامات من الفضة).","13:22":"ولم يكن لدى جميع الجيش الباقي مع شاول ويوناثان في يوم الحرب أي سيف أو رمح، إلا ما كان مع شاول ويوناثان ابنه.","13:23":"ومضت قوة من الفلسطينيين لتعسكر في ممر مخماس.","14:1":"وذات يوم قال يوناثان بن شاول للغلام حامل سلاحه: «تعال نمض إلى حامية الفلسطينيين المعسكرة في ذلك الممر». ولكنه لم يخبر أباه بذلك.","14:2":"وكان شاول ورجاله الست مئة مقيمين في طرف جبعة تحت شجرة الرمان في مغرون.","14:3":"ومن جملتهم كان أخيا بن أخيطوب أخي إيخابود بن فينحاس بن عالي، كاهن الرب في شيلوه، وكان لابسا أفودا، ولم يعلم أحد من الجيش بذهاب يوناثان.","14:4":"وكان من بين الممرات التي التمس يوناثان عبورها، لكي يتسلل إلى حامية الفلسطينيين، ممر ضيق بين صخرتين مسنونتين، تسمى إحداهما بوصيص والأخرى تسمى سنه،","14:5":"وكانت إحداهما تنتصب كعمود إلى الشمال مقابل مخماس، والأخرى إلى الجنوب مقابل جبعة.","14:6":"فقال يوناثان للغلام حامل سلاحه: «نذهب إلى خطوط هؤلاء الغلف، لعل الله يجري من أجلنا أمرا عظيما، إذ لا يمتنع عن الرب أن يخلص بالعدد الكثير أو بالقليل».","14:7":"فأجابه: «افعل ما استقر عليه قلبك. تقدم، وها أنا معك في كل ما عزمت عليه».","14:8":"فقال يوناثان: «لنعبر صوب القوم ونظهر لهم أنفسنا.","14:9":"فإن قالوا لنا: انتظروا ريثما نأتي إليكم. نثبت في مكاننا ولا نتقدم نحوهم.","14:10":"ولكن إن قالوا لنا: تقدموا صوبنا، نتجه نحوهم، وتكون هذه علامة الرب لنا أنه ينصرنا عليهم».","14:11":"فأظهرا نفسيهما لحامية الفلسطينيين. فقال الفلسطينيون: «ها العبرانيون يبرزون من الجحور التي اختبأوا فيها».","14:12":"وقال رجال الحامية ليوناثان وحامل سلاحه: «تقدموا صوبنا لنلقي عليكما درسا». فقال يوناثان لحامل سلاحه: «اتبعني لأن الرب قد أسلمهم لإسرائيل».","14:13":"وتسلق يوناثان وحامل سلاحه على أيديهما وأرجلهما، وهاجمهم يوناثان. فكان الفلسطينيون يسقطون أمامه، فيسرع حامل سلاحه وراءه ويقضي عليهم.","14:14":"فقتل على إثر هذا الهجوم الأول نحو عشرين رجلا تبعثرت جثثهم في حوالي نصف فدان من الأرض.","14:15":"فانتاب الرعب المخيم والجيش المنتشر في الحقل وجميع الشعب، وارتعدت الحامية والغزاة، وحدثت هزة رجفت فيها الأرض وزادت من رعدتهم العظيمة.","14:16":"وشاهد مراقبو جيش شاول في جبعة بنيامين ما أصاب جيش الفلسطينيين من تبدد وتشتت.","14:17":"فأمر شاول رجاله أن يقوموا بإحصاء الموجودين لمعرفة الذين انطلقوا لمهاجمة الفلسطينيين فاكتشفوا غياب يوناثان وحامل سلاحه","14:18":"فقال شاول لأخيا: «أحضر تابوت الله». لأن تابوت الله كان في ذلك اليوم مع بني إسرائيل.","14:19":"وبينما كان شاول يتحدث مع الكاهن تزايد ضجيج معسكر الفلسطينيين، فقال شاول للكاهن: «كف يدك».","14:20":"وهتف شاول وجميع القوم الذين معه وأقبلوا على ساحة المعركة، وإذا بهم يشهدون سيف كل فلسطيني مسلطا على صاحبه، وقد فشا بينهم اضطراب عظيم.","14:21":"وانضم العبرانيون الذين التحقوا بالفلسطينيين من قبل وأقاموا معهم في المعسكر وما حوله إلى الإسرائيليين الذين مع شاول ويوناثان.","14:22":"وسمع جميع رجال إسرائيل الذين اختبأوا في جبل أفرايم أن الفلسطينيين فروا، فجدوا هم أيضا في تعقبهم وقتلهم.","14:23":"وهكذا أنقذ الرب إسرائيل في ذلك اليوم، وما لبثت ساحة الحرب أن انتقلت إلى ما وراء حدود بيت آون.","14:24":"وأعيا رجال إسرائيل في ذلك اليوم، لأن شاول حلف الشعب قائلا: «ملعون الرجل الذي يأكل طعاما إلى المساء حتى أنتقم من أعدائي». فلم يذق جميع القوم طعاما.","14:25":"وأقبل كل الجيش إلى الغابة حيث كان العسل يتقاطر،","14:26":"ولكن لم يجرؤ أحد أن يتذوق منه خوفا من لعنة الحلف.","14:27":"أما يوناثان فلم يكن حاضرا عندما استحلف والده القوم، فمد طرف عصاه التي كانت بيده وغمسه في قطر العسل وتذوق منه فانتعشت قوته.","14:28":"فقال له واحد من المحاربين: «قد حلف أبوك القوم قائلا: ملعون الرجل الذي يأكل اليوم طعاما»، فأصاب الشعب الإعياء.","14:29":"فقال يوناثان: «لقد أضر أبي بكل الجيش. انظروا كيف انتعشت قواي لأني ذقت قليلا من العسل.","14:30":"فكيف يكون حال الجيش لو أكل اليوم من غنائم أعدائه التي أحرزها؟ ألا تكون عندئذ كارثة الفلسطينيين أدهى وأمر؟»","14:31":"في ذلك اليوم ظل الإسرائيليون يتعقبون الفلسطينيين ويقتلونهم من مخماس إلى أيلون. وأصاب الجيش إعياء شديد.","14:32":"وهجم الجيش على الغنائم من الماشية وأخذوا غنما وبقرا وعجولا، وذبحوا على الأرض وأكلوا اللحم بدمه.","14:33":"فأخبر بعضهم شاول قائلين: «إن الجيش يرتكب خطيئة بحق الرب، إذ يأكلون اللحم مع الدم». فقال شاول: «لقد نقضتم عهدكم. دحرجوا إلي حجرا كبيرا،","14:34":"وتفرقوا بين الجيش وأمروهم أن يحضروا بقرهم وشياههم ليذبحوها عند الحجر، ويتركوها لتسيل دماؤها، فلا يرتكبون إثما في حق الرب بأكل الدم». وفعل الجنود ما أمر شاول به فأحضروا بقرهم وذبحوها هناك.","14:35":"وبنى شاول مذبحا للرب. فكان أول مذبح يشرع في بنائه.","14:36":"وأمر شاول: «لنتعقب الفلسطينيين ليلا ونظل ننهبهم إلى ضوء الصباح، ولا نبق منهم أحدا». فأجابوه: «افعل كل ما يطيب لك». ولكن الكاهن قال: «لنستشر الله هنا».","14:37":"فاستشار شاول الله سائلا: «أنتعقب الفلسطينيين؟ أتنصرنا عليهم؟» فلم يحظ بجواب في ذلك اليوم.","14:38":"فقال شاول: «اقتربوا إلى هنا يا جميع وجوه إسرائيل، وتقصوا أية خطيئة ارتكبت اليوم.","14:39":"لأنه حي هو الرب مخلص إسرائيل إن الموت هو جزاء مرتكب الخطيئة حتى لو كان جانيها ابني يوناثان». فاعتصم القوم بالصمت.","14:40":"فقال لكل الجيش: «قفوا أنتم في جانب، وأقف أنا وابني يوناثان في جانب آخر». فأجاب الشعب: «اصنع ما يروق لك».","14:41":"وصلى شاول للرب إله إسرائيل قائلا: «اكشف لي الحق». فوقعت القرعة على شاول ويوناثان، وتبرأ القوم.","14:42":"وقال شاول: «ألقوا القرعة بيني وبين يوناثان ابني». فوقعت القرعة على يوناثان.","14:43":"فقال شاول ليوناثان: «أخبرني ماذا جنيت؟» فقال يوناثان: «ذقت قليلا من العسل بطرف عصاي التي بيدي. أمن أجل قليل من العسل ينبغي أن أموت؟»","14:44":"فقال شاول: «ليضاعف الرب عقابي إن لم ينفذ بك حكم الموت».","14:45":"فهتف الجيش في وجه شاول: «أيموت يوناثان الذي صنع هذا الخلاص العظيم في إسرائيل؟ هذا لا يمكن! حي هو الرب، لا تسقط شعرة من رأسه إلى الأرض لأنه صنع هذا الأمر بمعونة الرب اليوم». وهكذا افتدى الشعب يوناثان فلم يمت.","14:46":"وكف شاول عن تعقب الفلسطينيين، فرجع الفلسطينيون إلى أرضهم.","14:47":"وتولى شاول كرسي الملك على إسرائيل وحارب جميع أعدائه المحيطين به، الموآبيين وبني عمون والأدوميين وملوك صوبة والفلسطينيين، فحالفه النصر حيثما توجه.","14:48":"وخاض معارك قاسية، فقهر عماليق وأنقذ الإسرائيليين من يد ناهبيهم.","14:49":"أما أبناء شاول فهم يوناثان ويشوي وملكيشوع، واسما ابنتيه ميرب وهي الكبرى، وميكال وهي الصغرى.","14:50":"وكانت امرأة شاول تدعى أخينوعم بنت أخيمعص، أما رئيس جيشه فكان أبنير بن نير عم شاول،","14:51":"إذ إن قيس أبا شاول ونير أبا أبنير كانا شقيقين، وهما ابنا أبيئيل.","14:52":"وتعرض الفلسطينيون لحرب قاسية طوال أيام حياة شاول. وكلما رأى شاول رجلا شجاعا وذا بأس كان يضمه إليه.","15:1":"وقال صموئيل لشاول: «أنا الذي أرسلني الرب لأنصبك ملكا على إسرائيل، فاسمع الآن كلام الرب.","15:2":"هذا ما يقوله رب الجنود: إني مزمع أن أعاقب عماليق جزاء ما ارتكبه في حق الإسرائيليين حين تصدى لهم في الطريق عند خروجهم من مصر.","15:3":"فاذهب الآن وهاجم عماليق واقض على كل ماله. لا تعف عن أحد منهم بل اقتلهم جميعا رجالا ونساء، وأطفالا ورضعا، بقرا وغنما، جمالا وحميرا».","15:4":"فاستدعى جيشه وأحصاه في طلايم، فبلغ عدده مئتي ألف راجل، فضلا عن عشرة آلاف رجل من سبط يهوذا.","15:5":"وتوجه شاول إلى مدينة عماليق وكمن في الوادي.","15:6":"وبعث شاول إلى القينيين قائلا: «انسحبوا من بين العمالقة لئلا أهلككم معهم، فأنتم قد أحسنتم إلى بني إسرائيل عند خروجهم من مصر». فانسحب القينيون من وسط العمالقة.","15:7":"وهجم شاول على العمالقة على طول الطريق من حويلة حتى مشارف شور مقابل مصر.","15:8":"وأسر أجاج ملك عماليق حيا، وقضى على جميع الشعب بحد السيف.","15:9":"وعفا شاول عن أجاج وعن خيار الغنم والبقر والعجول والخراف، وعن كل ما هو جيد، وأبوا أن يقضوا عليها، ولم يدمروا إلا الأملاك والغنائم التي لا قيمة لها.","15:10":"وقال الرب لصموئيل:","15:11":"«لقد ندمت لأني جعلت شاول ملكا، فقد ارتد عن اتباعي ولم يطع أمري». فحزن صموئيل وصلى إلى الرب الليل كله.","15:12":"وفي صباح اليوم التالي باكرا مضى صموئيل للقاء شاول، فقيل له: «لقد جاء شاول إلى الكرمل حيث أقام لنفسه نصبا تذكاريا، ثم التف وانحدر نحو الجلجال».","15:13":"وعندما التقى صموئيل بشاول، قال شاول: «ليباركك الرب. لقد نفذت أمر الرب»","15:14":"فسأل صموئيل: «وماذا تقول عن ثغاء الغنم وصوت الثيران التي تضج في مسامعي؟»","15:15":"فأجاب شاول: «إنها من غنائم العمالقة، لأن الشعب عفا عن خيار الغنم والبقر ليقدمها ذبائح للرب إلهك، وأما ما تبقى فقد دمرناه».","15:16":"فقال صموئيل لشاول: «اصمت لأنبئك بما تكلم به الرب إلي في هذه الليلة». فأجابه: «تكلم».","15:17":"فقال صموئيل: «ألم تكن تحسب نفسك حقيرا، ولكن الرب جعلك على رأس أسباط إسرائيل وأقامك ملكا عليهم،","15:18":"وكلفك بمحاربة عماليق والقضاء عليه قضاء مبرما؟","15:19":"فلماذا لم تطع أمر الرب، بل تهافت على الغنيمة وارتكبت الشر في عيني الرب؟»","15:20":"فأجاب شاول: «قد أطعت أمر الرب ونفذت ما عهد إلي به، وأسرت أجاج ملك عماليق وقضيت على شعبه.","15:21":"فاختار القوم من الغنيمة أفضل الغنم والبقر لتقريبها ذبائح للرب إلهك في الجلجال».","15:22":"فقال صموئيل: «هل يسر الرب بالذبائح والمحرقات كسروره بالاستماع إلى صوته؟ إن الاستماع أفضل من الذبيحة، والإصغاء أفضل من شحم الكباش.","15:23":"فالتمرد مماثل لخطيئة العرافة، والعناد شبيه بشر عبادة الوثن والإثم. ولأنك رفضت كلام الرب فقد رفضك الرب من الملك».","15:24":"فقال شاول: «لقد أخطأت لأني عصيت أمر الرب ووصيتك، إذ خشيت الشعب فسمعت لقولهم.","15:25":"فاصفح الآن عن خطيئتي وارجع معي لأسجد للرب»","15:26":"فقال صموئيل: «لن أرجع معك؛ لأنك رفضت كلام الرب رفضك الرب من أن تكون ملكا على إسرائيل».","15:27":"واستدار صموئيل ليمضي، فتشبث شاول بهدب جبته، فتمزق هدب الجبة.","15:28":"فقال له صموئيل: «يمزق الرب مملكة إسرائيل عنك ويهبها لمن هو خير منك.","15:29":"فإن قوة إسرائيل (أي الله) لا يكذب ولا يندم. ليس هو إنسانا حتى يغير رأيه».","15:30":"فقال شاول: «لقد أخطأت، ولكن أكرمني أمام شيوخ شعبي وأمام الإسرائيليين، وعد معي لأسجد للرب إلهك».","15:31":"فانطلق صموئيل مع شاول حيث سجد شاول للرب.","15:32":"ثم قال صموئيل: «قدموا إلي أجاج ملك العمالقة». فأقبل إليه أجاج فرحا قائلا لنفسه: «حقا قد تلاشت مرارة الموت».","15:33":"وقال له صموئيل: «كما أثكل سيفك النساء لتثكل كذلك أمك بين النساء». وقطع صموئيل أجاج إربا أمام الرب في الجلجال.","15:34":"ثم مضى صموئيل إلى الرامة، أما شاول فتوجه إلى بيته في جبعة شاول.","15:35":"وامتنع صموئيل عن رؤية شاول إلى يوم وفاته، مع أن قلبه تمزق أسى عليه. أما الرب فقد أسف لأنه أقام شاول ملكا على إسرائيل.","16:1":"وقال الرب لصموئيل: «إلى متى تظل تنوح على شاول وأنا قد رفضته أن يكون ملكا على إسرائيل؟ املأ قرنك بالزيت وتعال أرسلك إلى يسى المقيم في بيت لحم، لأني قد اخترت أحد أبنائه ليكون ملكا».","16:2":"فقال صموئيل: «كيف أذهب؟ إن بلغ شاول الأمر يقتلني». فأجابه الرب: «خذ معك عجلة وقل قد جئت لأذبح للرب.","16:3":"وادع يسى لحضور تقديم الذبيحة وأنا ألقنك ماذا تصنع، فتمسح لي من أقول لك عنه».","16:4":"ففعل صموئيل بموجب ما تكلم به الرب. وذهب إلى بيت لحم. فاضطرب شيوخ المدينة لدى استقباله وقالوا له: «هل للسلام حضرت؟»","16:5":"فأجاب: «نعم، للسلام. لقد حضرت لأقرب للرب. طهروا أنفسكم وتعالوا معي إلى الذبيحة». وقدس يسى أبناءه ودعاهم للذبيحة.","16:6":"وعندما أقبلوا وشاهد صموئيل أليآب بن يسى قال: «إن هذا هو مختار الرب».","16:7":"فقال الرب لصموئيل: «لا تلق بالا إلى وسامته وطول قامته إذ ليس هذا من اخترته، فنظرة الرب تختلف عن نظرة الإنسان، لأن الإنسان ينظر إلى المظهر الخارجي وأما الرب فإنه ينظر إلى القلب».","16:8":"ودعا يسى ابنه أبيناداب وأجازه أمام صموئيل، فقال: «وهذا أيضا لم يختره الرب».","16:9":"ثم قدم يسى شمة، فقال صموئيل: «وهذا أيضا لم يختره الرب».","16:10":"وعندما انتهى يسى من تقديم أبنائه السبعة، قال صموئيل ليسى: «إن الرب لم يختر واحدا من هؤلاء».","16:11":"ثم استطرد: «هل لك أبناء آخرون؟» فأجاب يسى: «بقي بعد أصغرهم وهو يرعى الغنم». فقال صموئيل ليسى: «أرسل من يأتي به لأننا لن نتكئ حتى يصل إلى هنا».","16:12":"فبعث يسى من استدعاه، وكان فتى أشقر، أخاذ العينين وسيم الطلعة. فقال الرب: « قم امسحه، لأن هذا هو من اخترته».","16:13":"فتناول صموئيل قرن الزيت ومسحه أمام إخوته. ومنذ ذلك اليوم فصاعدا حل روح الرب على داود. ثم رجع صموئيل إلى الرامة.","16:14":"وفارق روح الرب شاول وهاجمه من عند الرب روح رديء يعذبه.","16:15":"فقال له رجاله: «إن روحا رديئا يعذبك من عند الرب.","16:16":"فليأمر سيدنا خدامه الماثلين أمامه أن يبحثوا له عن رجل ماهر في العزف على العود، فيعزف أمامك كلما هاجمك الروح الرديء من عند الرب فتطيب نفسك».","16:17":"فطلب شاول من خدامه أن يبحثوا له عن رجل ماهر في العزف ويحضروه إليه.","16:18":"فقال واحد من الغلمان: «لقد شاهدت ابنا ليسى البيتلحمي ماهرا في العزف وهو بطل جبار ورجل حرب، فصيح اللسان وبهي الطلعة والرب معه».","16:19":"فأوفد شاول رسلا إلى يسى قائلا: «أرسل إلي داود ابنك الذي يرعى الغنم».","16:20":"فأعد يسى حمارا حمله خبزا وزق خمر وجدي معزى، وأرسلها مع داود إلى شاول.","16:21":"فمثل داود أمام شاول فأحبه وجعله حامل سلاحه.","16:22":"وأرسل شاول إلى يسى يقول: «دع داود يبقى في خدمتي لأنه قد حظي بإعجابي».","16:23":"وحدث عندما هاجم الروح الرديء المرسل من قبل الرب شاول، أن داود تناول العود وعزف عليه، فكان الهدوء يستولي على شاول وتطيب نفسه ويفارقه الروح الرديء.","17:1":"وحشد الفلسطينيون جيوشهم للحرب واجتمعوا في سوكوه التابعة لسبط يهوذا، وعسكروا ما بين سوكوه وعزيقة في أفس دميم.","17:2":"وتجمع شاول ورجاله ونزلوا في وادي البطم واصطفوا للحرب للقاء الفلسطينيين.","17:3":"ووقف الفلسطينيون على جبل من ناحية، والإسرائيليون على جبل آخر مقابلهم، يفصل بينهم واد.","17:4":"فخرج من بين صفوف جيوش الفلسطينيين رجل مبارز من جت يدعى جليات طوله ست أذرع وشبر (نحو ثلاثة أمتار)،","17:5":"يضع على رأسه خوذة من نحاس، ويرتدي درعا مصفحا وزنه خمسة آلاف شاقل (نحو سبعة وخمسين كيلو جراما) من النحاس","17:6":"وقد لف ساقيه بصفائح من نحاس، كما تدلى رمح نحاسي من كتفيه.","17:7":"وكانت قناة رمحه شبيهة بنول النساجين، وسنانه يزن ست مئة شاقل حديد (نحو سبعة كيلو جرامات)، وكان حامل ترسه يمشي أمامه.","17:8":"فوقف جليات ينادي جيش الإسرائيليين: «ما بالكم خرجتم تصطفون للحرب؟ ألست أنا الفلسطيني، وأنتم خدام شاول؟ انتخبوا من بينكم رجلا يبارزني.","17:9":"فإن استطاع محاربتي وقتلني نصبح لكم عبيدا، وإن قهرته وقتلته تصبحون أنتم لنا عبيدا وتخدموننا.","17:10":"إنني أعير وأتحدى اليوم جيش إسرائيل! ليخرج من بينكم رجل يبارزني!».","17:11":"وعندما سمع شاول وجميع إسرائيل تحديات الفلسطيني ارتعبوا وجزعوا جدا.","17:12":"وكان لداود بن يسى الأفراتي المقيم في بيت لحم أرض يهوذا، سبعة إخوة أكبر منه. وكان يسى قد شاخ في زمن شاول وتقدم في العمر.","17:13":"وكان بنو يسى الثلاثة الكبار قد التحقوا بجيش شاول وهم أليآب البكر وأبيناداب وشمة.","17:14":"أما داود فكان أصغر الأبناء جميعا. وانضم الثلاثة الكبار إلى صفوف شاول.","17:15":"وكان داود يتردد على شاول ثم يرجع من عنده ليرعى غنم أبيه في بيت لحم.","17:16":"وظل الفلسطيني يخرج متحديا الإسرائيليين كل صباح ومساء، مدة أربعين يوما.","17:17":"وذات يوم قال يسى لداود ابنه: «خذ لإخوتك إيفة (أي أربعة وعشرين لترا) من هذا الفريك، وعشرة أرغفة من الخبز واركض إلى المعسكر.","17:18":"وقدم عشر قطع من الجبن إلى قائد الألف، واطمئن على سلامة إخوتك وأحضر لي منهم ما يدل على سلامتهم».","17:19":"وكان شاول آنئذ مع جيشه ومن جملتهم إخوة داود، معسكرين في وادي البطم، تأهبا لمحاربة الفلسطينيين.","17:20":"فانطلق داود مبكرا في صباح اليوم التالي، بعد أن ترك الغنم في عهدة حارس، محملا بما أمره به أبوه، وبلغ المعسكر فيما كان الجيش خارجا للاصطفاف والهتاف للحرب.","17:21":"وما لبثت أن تواجهت صفوف الإسرائيليين والفلسطينيين.","17:22":"فترك داود الطعام الذي يحمله في رعاية حافظ الأمتعة، وهرول نحو خط القتال يبحث عن إخوته ليطمئن على سلامتهم.","17:23":"وفيما هو يحادثهم إذا بجليات الفلسطيني المبارز من جت، يخرج من صفوف الفلسطينيين، ويوجه تحدياته إلى الإسرائيليين. فأصغى داود إلى تهديداته.","17:24":"وعندما شاهد جيش إسرائيل الرجل تراجعوا أمامه مذعورين جدا.","17:25":"وتحدث رجال إسرائيل فيما بينهم: «أرأيتم هذا الرجل المبارز من صفوف الفلسطينيين؟ إنه يسعى لتحدينا وتعييرنا. إن من يقتله يغدق عليه الملك ثروة طائلة، ويزوجه من ابنته، ويعفي بيت أبيه من دفع الضرائب ومن التسخير».","17:26":"فسأل داود الرجال الواقفين إلى جواره: «بماذا يكافأ الرجل الذي يقتل ذلك الفلسطيني ويمحو العار عن إسرائيل؟ لأنه من هو هذا الفلسطيني الأغلف حتى يعير جيش الله الحي؟»","17:27":"فتلقى داود من الجنود جوابا مماثلا لما سمعه من قبل عن المكافأة التي ينالها الرجل الذي يقتل جليات.","17:28":"وسمع أخوه الأكبر حديثه مع الرجال، فاحتدم غضبه على داود وقال: «لماذا جئت إلى هنا؟ وعلى من تركت تلك الغنيمات القليلة في البرية؟ لقد عرفت غرورك وشر قلبك، فأنت لم تحضر إلى هنا إلا لتشهد الحرب».","17:29":"فأجاب داود: «أية جناية ارتكبت الآن؟ ألا يحق لي حتى أن أوجه سؤالا؟»","17:30":"وتحول عن أخيه نحو قوم آخرين، أثار معهم نفس الموضوع، فأجابوه بمثل الجواب السابق.","17:31":"وبلغ شاول حديث داود، فاستدعاه.","17:32":"وقال داود لشاول: «لا يذوبن قلب أحد خوفا من هذا الفلسطيني، فإن عبدك يذهب ليحاربه»","17:33":"فقال شاول لداود: «أنت لا يمكنك الذهاب لمحاربة هذا الفلسطيني، لأنك مازلت فتى، وهو رجل حرب منذ صباه».","17:34":"فقال داود: «كان عبدك يرعى ذات يوم غنم أبيه، فجاء أسد مع دب واختطف شاة من القطيع.","17:35":"فسعيت وراءه وهاجمته وأنقذتها من أنيابه. وعندما انقض علي قبضت عليه من ذقنه وضربته فقتلته.","17:36":"وهكذا قتل عبدك الأسد والدب كليهما، فليكن هذا الفلسطيني الأغلف كواحد منهما لأنه عير جيش الله الحي».","17:37":"واستطرد داود: «إن الرب الذي أنقذني من مخالب الأسد ومن مخالب الدب، ينقذني أيضا من قبضة هذا الفلسطيني». فقال شاول لداود: «امض وليكن الرب معك».","17:38":"وألبس شاول داود سترة حربه، ووضع على رأسه خوذة من نحاس ومنطقه بدرع.","17:39":"وتقلد داود سيف شاول، وهم أن يمشي، وإذ لم يكن قد تعود عليها من قبل قال لشاول: «لا أقدر أن أمشي بعدة الحرب هذه، لأنني لست معتادا عليها». وخلعها عنه.","17:40":"وتناول عصاه بيده، ثم التقط خمسة حجارة ملساء من جدول الوادي وجعلها في جرابه، وحمل مقلاعه بيده واتجه نحو جليات.","17:41":"وتقدم الفلسطيني نحو داود، وحامل سلاحه يمشي أمامه.","17:42":"وما إن شاهد الفلسطيني داود حتى استخف به لأنه كان فتى أشقر وسيم الطلعة.","17:43":"فقال الفلسطيني لداود: «ألعلي كلب حتى تأتي لمحاربتي بعصي؟» وشتم الفلسطيني آلهة داود.","17:44":"ثم قال لداود: «تعال لأجعل لحمك طعاما لطيور السماء ووحوش البرية».","17:45":"فأجابه داود: «أنت تبارزني بسيف ورمح وترس، أما أنا فآتيك باسم رب الجنود إله جيش إسرائيل الذي تحديته.","17:46":"اليوم يوقعك الرب في يدي، فأقتلك وأقطع رأسك، وأقدم جثث جيش الفلسطينيين هذا اليوم لتكون طعاما لطيور السماء وحيوانات الأرض، فتعلم المسكونة كلها أن هناك إلها في إسرائيل.","17:47":"وتدرك الجموع المحتشدة هنا أنه ليس بسيف ولا برمح يخلص الرب، لأن الحرب للرب وهو ينصرنا عليكم».","17:48":"وعندما شاهد داود الفلسطيني يهب متقدما نحوه، أسرع للقائه.","17:49":"ومد يده إلى الجراب، وتناول حجرا لوح به بمقلاعه ورماه، فأصاب جبهة الفلسطيني، فغاص الحجر في جبهته وسقط جليات على وجهه إلى الأرض.","17:50":"وهكذا قضى داود على الفلسطيني بالمقلاع والحجر وقتله. وإذ لم يكن بيده سيف","17:51":"ركض نحو جليات واخترط سيفه من غمده وقتله وقطع به رأسه. فلما رأى الفلسطينيون أن جبارهم قد قتل هربوا.","17:52":"فأطلق رجال إسرائيل ويهوذا صيحات الحرب، وتعقبوا الفلسطينيين حتى مشارف الوادي وأبواب مدينة عقرون. وانتشرت جثث قتلى الفلسطينيين على طول طريق شعرايم إلى جت وإلى عقرون.","17:53":"وعندما رجع الإسرائيليون من مطاردة الفلسطينيين هجموا على معسكرهم ونهبوه.","17:54":"وحمل داود رأس جليات إلى أورشليم، ولكنه احتفظ بعدة حربه في خيمته.","17:55":"وكان شاول عندما رأى داود خارجا لمحاربة جليات، قد سأل أبنير قائد جيشه: «ابن من هذا الفتى يا أبنير؟» فأجابه: «وحياتك أيها الملك لست أعلم».","17:56":"فقال الملك: «اسأل ابن من هذا الفتى؟»","17:57":"وحين رجع داود بعد قتل الفلسطيني أخذه أبنير وأحضره للمثول أمام شاول، ورأس الفلسطيني ما برح بيده.","17:58":"فسأله شاول: «ابن من أنت يا فتى؟» فأجابه داود: «ابن عبدك يسى البيتلحمي».","18:1":"وعندما فرغ داود من حديثه مع شاول، تعلقت نفس يوناثان بداود وأحبه كنفسه.","18:2":"واستبقى شاول داود، ولم يدعه يرجع إلى بيت أبيه.","18:3":"وتعاهد يوناثان وداود، لأن يوناثان أحبه كنفسه.","18:4":"وخلع يوناثان جبته ووهبها لداود مع ثيابه وسيفه وقوسه وحزامه.","18:5":"وكان النجاح حليف داود في كل مهمة كلفه بها شاول، لذلك ولاه شاول إمرة رجال الحرب، فحظي ذلك باستحسان الشعب وعبيد شاول أيضا.","18:6":"وعند رجوع الجيش بعد مقتل جليات، خرجت النساء من جميع مدن إسرائيل بالغناء والرقص، وبدفوف الفرح وبمثلثات لاستقبال شاول الملك.","18:7":"وراحت النساء الراقصات ينشدن: «قتل شاول ألوفه وقتل داود ربواته (أي عشرات الألوف)».","18:8":"فأثار هذا غضب شاول، وساء هذا الغناء في نفسه وقال: «نسبن لداود قتل عشرات الألوف، أما أنا فنسبن لي قتل الألوف فقط! لم يبق سوى أن ينعمن عليه بالمملكة».","18:9":"وشرع شاول منذ ذلك اليوم فصاعدا يراقب داود بعين ممتلئة بالغيرة.","18:10":"وحدث في اليوم التالي أن هاجم الروح الرديء شاول من قبل الرب، فبدأ يهذي جنونا في وسط البيت، بينما كان داود يعزف كعادته في كل يوم. وكان في يد شاول رمح،","18:11":"فأشرع شاول الرمح وقال في نفسه: «سأسمر داود إلى الحائط». فراغ داود من أمامه مرتين.","18:12":"وصار شاول يخشى داود لأن الرب كان معه، وقد فارق شاول.","18:13":"فأبعده من حضرته وعينه قائد ألف، فكان داود يتقدم دائما في طليعة فرقته.","18:14":"وحالفه الفلاح في كل أعماله لأن الرب كان معه.","18:15":"وعندما رأى شاول ما يتمتع به داود من فطنة تفاقم فزعه منه.","18:16":"أما جميع إسرائيل ويهوذا فقد ازدادوا حبا له، لأنه كان دائما يقودهم في حملاتهم العسكرية الموفقة.","18:17":"وقال شاول لداود: «إنني أبغي أن أزوجك من ابنتي الكبيرة ميرب، شريطة أن تكون بطلا وتحارب حروب الرب» فقد حدث شاول نفسه قائلا: «لا أحمل أنا جريرة قتله بل يقتله الفلسطينيون».","18:18":"فأجاب داود: «من أنا وما هي حياتي؟ وما هي عائلتي وما هي مكانة عائلتي في إسرائيل حتى أصبح صهرا للملك؟»","18:19":"وعندما اقترب موعد زفاف ميرب لداود، زوجها شاول من عدريئيل المحولي.","18:20":"لكن ميكال ابنة شاول الصغرى أحبت داود، فعلم شاول بالأمر وحظي ذلك برضاه.","18:21":"وقال شاول في نفسه: «أزوجه منها فتكون له فخا، وكذلك يسعى الفلسطينيون إلى قتله». وقال شاول لداود مرة ثانية: «يمكنك مصاهرتي اليوم».","18:22":"وأمر شاول رجاله أن يسروا في أذن داود أن الملك يحبه، وأنه محل إعجاب الحاشية، وأن ينصحوه بمصاهرة الملك،","18:23":"فراح عبيد شاول يسرون بهذا الحديث في مسامع داود. فأجاب داود: «أتظنون مصاهرة الملك أمرا تافها؟ أنا لست سوى رجل مسكين حقير».","18:24":"فأخبر عبيد شاول سيدهم بحديث داود.","18:25":"فقال شاول لهم: «هذا ما تقولونه لداود: إن الملك لا يطمع في مهر، بل في مئة غلفة من غلف الفلسطينيين، انتقاما من أعداء الملك». قال هذا ظنا منه أن يوقع داود في أسر الفلسطينيين.","18:26":"فأبلغ عبيد شاول داود بمطلب الملك، فراقه الأمر، ولا سيما فكرة مصاهرة الملك. وقبل أن تنتهي المهلة المعطاة له،","18:27":"انطلق مع رجاله وقتل مئتي رجل من الفلسطينيين، وأتى بغلفهم وقدمها كاملة لتكون مهرا لمصاهرة الملك. فزوجه شاول عندئذ من ابنته ميكال.","18:28":"وأدرك شاول يقينا أن الرب مع داود، وأن ابنته ميكال تحبه.","18:29":"فتزايد خوف شاول من داود، وأصبح عدوه اللدود طوال حياته.","18:30":"وثابر أقطاب الفلسطينيين على محاربة إسرائيل، فكان داود يظفر بهم أكثر من بقية قواد شاول، وأصبح اسمه على كل شفة ولسان.","19:1":"وحض شاول ابنه يوناثان وسائر حاشيته على قتل داود،","19:2":"ولكن يوناثان بن شاول، الذي كان معجبا جدا بداود، أسر إليه قائلا: «أبي يلتمس قتلك، فاحترس لنفسك في الغد واختبئ،","19:3":"وأنا أخرج مع أبي إلى الحقل الذي تختبئ فيه، وأحدثه عنك ثم أخبرك بما يكون».","19:4":"وراح يوناثان يثني على داود أمام أبيه وتساءل: «لماذا يسيء الملك إلى عبده داود، فإنه لم يخطئ إليك، ومآثره عظيمة جدا؟","19:5":"لقد عرض حياته للخطر عندما قتل الفلسطيني، فأجرى الرب خلاصا عظيما لجميع إسرائيل. وقد شهدت ذلك وابتهجت به. فلماذا تقتل داود من غير داع وتسيء إلى دم بريء؟»","19:6":"فاقتنع شاول بكلام يوناثان، وقال: «أقسم بالله الحي، لن يقتل داود».","19:7":"فاستدعى يوناثان داود وأطلعه على ما دار من حديث، ثم جاء به إلى شاول، فمثل في حضرته كما كان يفعل من قبل.","19:8":"وعادت الحرب تنشب من جديد، فخرج داود لمحاربة الفلسطينيين وهزمهم هزيمة منكرة، فلاذوا بالفرار من أمامه.","19:9":"وذات يوم كان داود يعزف لشاول، فهاجم الروح الرديء شاول من لدى الرب وهو جالس في بيته، ورمحه بيده.","19:10":"فصوب الرمح نحو داود ورماه به ليطعنه ويسمره إلى الحائط، فتفادى داود الضربة، وهرب من أمام شاول ناجيا بحياته تلك الليلة، أما الرمح فغاص في الحائط.","19:11":"فأرسل شاول مراقبين إلى بيت داود يترصدونه ليقتلوه في الصباح. فأخبرته امرأته ميكال قائلة: «إذا لم تنج بنفسك هذه الليلة فإنك لا محالة تقتل غدا».","19:12":"ودلته ميكال من النافذة، فانطلق هاربا ونجا.","19:13":"ثم أخذت ميكال تمثالا ووضعته في فراشه، ووضعت تحت رأسه لبدة من شعر المعزى وغطته بثوب.","19:14":"وعندما أرسل شاول جنوده للقبض على داود قالت لهم ميكال: «إنه مريض».","19:15":"فبعث شاول الجنود ثانية ليروا داود قائلا: «ائتوني به وهو في السرير لأقتله».","19:16":"فأقبل الجنود، وإذا في الفراش تمثال ولبدة من شعر المعزى تحت رأسه.","19:17":"فقال شاول لابنته ميكال: «لماذا خدعتني فأطلقت عدوي حتى نجا؟» فأجابت: «لقد توعدني قائلا: أطلقيني لئلا أقتلك».","19:18":"وعندما هرب داود ونجا بحياته جاء إلى صموئيل في الرامة وأطلعه عما فعله به شاول، وصحبه صموئيل ومضيا وأقاما معا في نايوت.","19:19":"فقيل لشاول: «هوذا داود في نايوت في الرامة».","19:20":"فبعث بجنود للقبض عليه. ولكن عندما شاهدوا جماعة الرب يتنبأون برئاسة صموئيل، حل روح الرب على الجنود فتنبأوا هم أيضا.","19:21":"فأخبروا شاول بالأمر، فبعث بجنود آخرين فتنبأوا هم أيضا. ثم عاد شاول فأرسل فرقة ثالثة فتنبأوا هم أيضا.","19:22":"وأخيرا ذهب بنفسه إلى الرامة، حتى وصل إلى البئر العظيمة التي عند سيخو وسأل: «أين صموئيل وداود؟» فقيل له: «هما في نايوت في الرامة».","19:23":"فمضى إلى هناك ولكن في أثناء الطريق حل عليه روح الرب، فشرع يتنبأ حتى بلغ نايوت في الرامة.","19:24":"فخلع هو أيضا ثيابه وراح يتنبأ أمام صموئيل، ثم انطرح عاريا طول ذلك النهار والليل، لذلك قيل: «أشاول أيضا بين الأنبياء؟».","20:1":"وهرب داود من نايوت في الرامة والتقى بيوناثان وسأله: «ماذا جنيت، وماذا اقترفت من إثم في حق أبيك حتى يصر على قتلي؟»","20:2":"فأجابه: «معاذ الله أن تموت! فإن أبي لا يقدم على أمر كبير أم صغير من غير أن يطلعني عليه، فلماذا يخفي عني أمرا كهذا؟ إن مخاوفك لا أساس لها من الصحة».","20:3":"فأقسم داود قائلا: «إن أباك يدرك أنني حظيت برضاك، لذلك قال في نفسه: لأكتمن الأمر عن يوناثان لئلا يطغى عليه الغم. ولكني أقسم لك بالله الحي، كما أقسم بحياتك، إنه ليس بيني وبين الموت سوى خطوة».","20:4":"فأجاب يوناثان: «مهما تطلبه نفسك أفعله لك».","20:5":"فقال داود ليوناثان: «غدا هو الاحتفال بأول أيام الشهر، حيث من عادتي أن أجلس مع الملك حول مائدة الأكل ولكن دعني أذهب فأختبئ في الحقل إلى مساء اليوم الثالث.","20:6":"فإذا افتقدني أبوك، فقل له: قد استأذن مني في الذهاب إلى بيت لحم مدينته للمشاركة في الذبيحة السنوية التي تقام لكل العشيرة.","20:7":"فإن قال: حسنا، فمعنى ذلك أن خادمك في أمان. ولكن إن اشتعل غيظا فاعلم أنه يضمر لي الشر.","20:8":"أما أنت فتكون قد صنعت خيرا مع خادمك، وفاء بما قطعت له من عهد أشهدت عليه الرب. وإن كان في إثم فخير أن تقتلني أنت من أن تسلمني لأبيك».","20:9":"فقال يوناثان: «معاذ الله أن يحدث ذلك، لأنه لو علمت أن أبي يضمر لك شرا، أفما كنت أخبرك؟»","20:10":"وتساءل داود: «من يخبرني إن رد عليك أبوك بجواب فظ؟»","20:11":"فأجابه يوناثان: «تعال نخرج إلى الحقل». فانطلقا معا إلى الحقل.","20:12":"وهناك قال يوناثان لداود: «ليكن الرب إله إسرائيل شاهدا أنه إن كشفت عن نية أبي من نحوك غدا أو بعد غد، في مثل هذا الوقت، فوجدت أنه يكن لك الخير ولم أرسل لأطلعك عليه،","20:13":"فليعاقب الرب يوناثان أشد عقوبة ويزد. وإن أضمر لك أبي سوءا فإنني أخبرك وأطلقك، فتنصرف بسلام، وليكن الرب معك كما كان مع أبي.","20:14":"ولا تقصر خير الرب علي في أثناء حياتي.","20:15":"بل احفظ العهد نفسه مع عائلتي إلى الأبد، حتى حين يقضي الرب على جميع أعدائك».","20:16":"وهكذا أبرم يوناثان عهدا مع بيت داود قائلا: «وليعاقبك الرب بيد أعدائك إن خنت العهد».","20:17":"ثم عاد يوناثان يستحلف داود بمحبته له لأنه أحبه كمحبته لنفسه.","20:18":"وقال له يوناثان: «غدا يكون الاحتفال بأول الشهر فيفتقدونك لأن موضعك يكون خاليا.","20:19":"وفي اليوم الثالث، عند حلول المساء، تأتي مسرعا إلى الموضع الذي اختبأت فيه عندما لم يكن زمام الأمر قد أفلت بعد، وتجلس إلى جوار حجر الافتراق.","20:20":"فأرمي أنا ثلاثة سهام إلى جانبه وكأنني أستهدف غرضا.","20:21":"وعندئذ أرسل الغلام قائلا: «اذهب والتقط السهام» فإن قلت له: ها السهام إلى جانبك فأحضرها تعال، لأنه حي هو الرب، أنت في أمان ولا خطر عليك.","20:22":"ولكن إن قلت للغلام: ها السهام أمامك فتقدم فامض لأن الرب قد أطلقك.","20:23":"أما ما جرى بيننا من حديث فليكن الرب شاهدا عليه إلى الأبد.","20:24":"فاختبأ داود في الحقل. وفي أول يوم من الشهر جلس الملك لتناول الطعام","20:25":"في مقعده المعتاد عند الحائط، وجلس يوناثان في مواجهته. أما أبنير فقد احتل مقعدا إلى جوار شاول.","20:26":"ولم يعلق شاول في ذلك اليوم على غياب داود، ظنا منه أن عارضا قد ألم به وأنه غير طاهر طبقا للشريعة.","20:27":"ولكن عندما خلا موضع داود في اليوم الثاني من الشهر، سأل شاول يوناثان ابنه: «لماذا تغيب ابن يسى عن الطعام أمس واليوم؟»","20:28":"فأجاب يوناثان: «لقد استأذن داود مني للذهاب إلى بيت لحم،","20:29":"وقال: دعني أذهب لأن عشيرتي تقدم ذبيحة في المدينة، وقد أوصاني أخي بالحضور. فإن حظيت برضاك فدعني أمضي لأرى إخوتي، لذلك تغيب عن مائدة الملك».","20:30":"فاستشاط شاول غضبا على يوناثان وقال له: «يا ابن المتعوجة المتمردة، أتظن أنني لم أعلم أن انحيازك لابن يسى يفضي إلى خزيك وخزي أمك التي أنجبتك؟","20:31":"فمادام ابن يسى حيا فإنك لا تستقر أنت ولا مملكتك. والآن أرسل واقبض عليه، وأت به لأنه محكوم عليه بالموت».","20:32":"فأجاب يوناثان: «لماذا يقتل، وأي ذنب جناه؟»","20:33":"فصوب شاول الرمح نحوه ليطعنه، فأدرك يوناثان على الفور أن والده مصر على قتل داود.","20:34":"فغادر المائدة والغضب الجامح يعصف به، من غير أن يقرب الطعام إذ ساءه تصرف والده المخزي من نحو داود. وكان ذلك في اليوم الثاني من أول الشهر.","20:35":"وخرج في صباح اليوم الثالث إلى الحقل كما اتفق مع داود، يرافقه غلام صغير.","20:36":"فقال لغلامه: «أسرع والتقط السهام التي أرمي بها». وبينما كان الغلام راكضا رمى السهم حتى جاوز الغلام.","20:37":"وعندما وصل الغلام إلى موضع السهم الذي رماه نادى يوناثان الغلام: «أليس السهم أمامك؟»","20:38":"ثم عاد يهتف به: «عجل أسرع! لا تقف». فالتقط الغلام السهم وجاء به إلى سيده.","20:39":"ولم يعلم الغلام بما يجري، أما يوناثان وداود فهما وحدهما اللذان كانا مطلعين على الأمر.","20:40":"فعهد يوناثان بسلاحه إلى الغلام قائلا له: «اذهب، وادخل به إلى المدينة».","20:41":"وما إن توارى الغلام عن الأنظار حتى برز داود من الجهة الجنوبية وسقط على وجهه إلى الأرض ساجدا ثلاث مرات، وقبل كل منهما صاحبه، وبكيا معا. وكان بكاء داود أشد مرارة.","20:42":"وقال يوناثان لداود: «امض بسلام لأننا كلينا حلفنا على صداقتنا باسم الرب قائلين: ليكن الرب شاهدا بيني وبينك، وبين نسلي ونسلك إلى الأبد». ثم افترقا. فذهب داود في طريقه، أما يوناثان فرجع إلى المدينة.","21:1":"وقدم داود إلى أخيمالك الكاهن في نوب، فارتعد أخيمالك عند لقاء داود وسأله: «مالي أراك وحدك وليس معك أحد؟».","21:2":"فأجابه داود: «كلفني الملك بمهمة وأمرني أن أكتم الأمر فلا أخبر به أحدا، وأما رجالي فقد اتفقت معهم على مقابلتي في مكان معين.","21:3":"والآن ماذا عندك من الطعام؟ أعطني خمسة أرغفة أو ما يتوافر لديك».","21:4":"فأجاب الكاهن: «ليس عندي خبز عادي، وإنما خبز مقدس، يمكن لرجالك أن يأكلوا منه شريطة أن يكونوا قد حفظوا أنفسهم طاهرين ولاسيما من النساء».","21:5":"فقال داود للكاهن: «إن النساء قد منعن عنا منذ أمس وما قبل، كما هي العادة عند خروجي في مهمة، أما أمتعتهم فهي دائما طاهرة، حتى في أثناء تنفيذ المهمات العادية. فكم بالحري إن كانت المهمة مقدسة؟»","21:6":"فأعطاه الكاهن الخبز المقدس إذ لم يكن لديه سوى خبز الوجوه المرفوع من أمام الرب لكي يستبدل بخبز ساخن في اليوم الذي يرفع فيه.","21:7":"وكان هناك رجل من خدم شاول معتكفا في ذلك اليوم أمام الرب، يدعى دواغ الأدومي، رئيس رعاة شاول.","21:8":"وسأل داود أخيمالك: «ألا يوجد لديك رمح أو سيف، لأنني لم أتقلد سيفي أو أحمل سلاحي، إذ إن أمر الملك كان ملحا».","21:9":"فأجاب الكاهن: «عندي سيف جليات الفلسطيني الذي قتلته في وادي البطم، وها هو ملفوف في ثوب خلف الأفود. فإن شئت أن تأخذه فافعل، لأنه ليس عندي سواه هنا». فقال داود: «ليس له مثيل، أعطني إياه».","21:10":"في ذلك اليوم هرب داود من أمام شاول ولجأ إلى أخيش ملك جت.","21:11":"فقال رجال حاشية أخيش له: «أليس هذا داود ملك بلاده؟ أليس هذا الذي أنشدت له النساء راقصات قائلات: قتل شاول ألوفا وقتل داود عشرات الألوف؟»","21:12":"فكتم داود هذا الكلام في نفسه وتولاه خوف شديد من أخيش ملك جت،","21:13":"وتظاهر أمامهم أنه مصاب بعقله، وراح يخربش على الباب وترك لعابه يسيل على لحيته.","21:14":"فقال أخيش لقومه: «ألا ترون أن الرجل مجنون، فلماذا جئتم به إلي؟","21:15":"ألا يكفيني ما عندي من مجانين حتى أتيتم بهذا لكي يظهر جنونه علي؟ أيدخل هذا بيتي؟».","22:1":"وهرب داود من جت ولجأ إلى مغارة عدلام، فلما سمع إخوته وسائر بيت أبيه بوجوده هناك جاءوا إليه.","22:2":"وانضم إليه نحو أربع مئة رجل من المتضايقين والمديونين والثائرين، فترأس عليهم.","22:3":"ثم انتقل داود من هناك إلى مصفاة موآب، وقال لملك موآب: «دع أبي وأمي في عهدتكم ريثما أعلم ما يصنع بي الله».","22:4":"فأودعهما عند ملك موآب، فأقاما عنده طوال مدة إقامة داود في الحصن.","22:5":"فقال جاد النبي لداود «لا تقم في الحصن، بل امض وادخل أرض يهوذا». فانتقل داود إلى غابة حارث.","22:6":"وبلغ شاول ما أصاب داود ورجاله من شهرة. وكان شاول آنئذ مقيما في جبعة، يجلس تحت الأثلة في الرامة محاطا بأفراد حاشيته، ورمحه بيده.","22:7":"فقال شاول لرجاله: «استمعوا يا بنيامينيون: ألعل ابن يسى يعطيكم جميعا حقولا وكروما أو يجعلكم جميعا رؤساء على ألوف الجنود أو على مئات منهم،","22:8":"حتى تحالفتم كلكم علي، فلم يخبرني أحد منكم بالعهد الذي أبرمه ابني مع ابن يسى، وليس بينكم من يأسى لي أو ينبئني بأن ابني قد أثار خادمي ليكمن لي كما يفعل اليوم؟»","22:9":"فأجاب دواغ الأدومي الذي كان واقفا بين حاشية شاول: «لقد شاهدت ابن يسى قادما إلى نوب إلى أخيمالك بن أخيطوب","22:10":"فاستشار له الرب وزوده بطعام وأعطاه سيف جليات».","22:11":"فاستدعى الملك أخيمالك وبقية بيت أبيه من كهنة نوب، فأقبلوا جميعا إلى الملك.","22:12":"فقال شاول: «اسمع يا ابن أخيطوب». فأجاب: «نعم يا سيدي».","22:13":"فقال له شاول: «لماذا اتفقتم علي أنت وابن يسى بتزويدك إياه بالخبز وبإعطائه سيفا، واستشرت له الله ليثور علي ويكمن لي كما يفعل هذا اليوم؟»","22:14":"فأجاب أخيمالك: «أي واحد من بين جميع رجالك مثل داود أمين وصهر الملك وقائد حرسه وذو مكانة رفيعة في بيتك؟","22:15":"فهل هذه هي أول مرة أستشير له فيها الله؟ معاذ الله أن يتهمني الملك أو يتهم جميع بيت أبي بارتكاب شيء».","22:16":"فقال الملك: «إنك لا محالة مائت يا أخيمالك، أنت وجميع بيت أبيك».","22:17":"وأمر الملك حراسه الماثلين لديه: «هيا أحيطوا بكهنة الرب واقتلوهم، لأنهم أيضا قد تحالفوا مع داود، ولأنهم عرفوا أنه كان هاربا فلم يخبروني». فلم يرض حراس الملك أن يقتلوا كهنة الرب.","22:18":"فأمر الملك دواغ قائلا: «در أنت واقتل الكهنة». فهجم دواغ الأدومي على الكهنة وقتل منهم في ذلك اليوم خمسة وثمانين رجلا لابسي أفود كتان.","22:19":"ثم اقتحم نوب مدينة الكهنة وقتل بحد السيف الرجال والنساء والأطفال والرضع والثيران والحمير والغنم.","22:20":"ولم ينج سوى ابن واحد لأخيمالك بن أخيطوب يدعى أبياثار الذي لجأ إلى داود،","22:21":"وأخبره أن شاول قد قتل كهنة الرب.","22:22":"فقال داود لأبياثار: «عندما رأيت دواغ هناك في ذلك اليوم أدركت أنه لابد أن يخبر شاول. أنا هو السبب في موت أفراد بيت أبيك.","22:23":"امكث معي، لا تخف، فالرجل الذي يسعى لقتلك يسعى لقتلي أيضا، فأقم عندي بأمان».","23:1":"وقيل لداود: «ها الفلسطينيون يهاجمون قعيلة وينهبون بيادر قمحها»","23:2":"فسأل الرب: «هل أمضي لمحاربة الفلسطينيين؟» فأجابه الرب: «اذهب وحاربهم وأنقذ قعيلة».","23:3":"ولكن رجال داود قالوا: «إن كان الخوف يستبد بنا ونحن هنا في يهوذا، فكم بالحري إذا انطلقنا إلى قعيلة لمحاربة جيوش الفلسطينيين؟»","23:4":"فعاد داود يستشير الرب، فأجابه: «قم انزل إلى قعيلة، فإنني أسلم الفلسطينيين إلى يدك».","23:5":"فمضى داود ورجاله إلى قعيلة حيث حارب الفلسطينيين واستولى على مواشيهم وهزمهم هزيمة منكرة وأنقذ أهل قعيلة.","23:6":"وكان أبياثار بن أخيمالك قد حمل معه أفودا عند هروبه إلى داود.","23:7":"فقيل لشاول إن داود قد قدم إلى قعيلة، فقال شاول: «قد أسلمه الله إلى يدي، لأنه لجأ إلى مدينة ذات بوابات وأرتاج».","23:8":"واستدعى شاول قواته للإحاطة بالمدينة ومحاصرة داود ورجاله.","23:9":"ولما أدرك داود أن شاول يتآمر عليه، قال لأبياثار الكاهن: «أحضر الأفود».","23:10":"ثم صلى داود: «يا رب إله إسرائيل، إن عبدك قد سمع أن شاول يحاول أن يحاصر قعيلة ليدمرها","23:11":"فأعلمني هل يسلمني أهل قعيلة لشاول؟ وهل شاول حقا قادم إلى قعيلة كما قيل لعبدك؟ يا رب إله إسرائيل أخبر عبدك». فأجاب الرب: «إنه قادم».","23:12":"وعاد داود يسأل: «هل يسلمني أهل قعيلة مع رجالي لشاول؟» فأجاب الرب: «يسلمون».","23:13":"فغادر داود ورجاله الست مئة قعيلة وهاموا على وجوههم. فأخبر شاول بانسحاب داود من قعيلة، فعدل عن التوجه إليها بقواته.","23:14":"ولجأ داود إلى حصون برية زيف ومكث في جبلها. وظل شاول يتعقبه طوال أيام حياته، ولكن الرب لم يسلمه ليده.","23:15":"وبينما كان داود مختبئا في غابة في برية زيف علم أن شاول قد خرج يبحث عنه،","23:16":"فأقبل يوناثان بن شاول إلى داود في الغابة ليقوي من ثقته بالله،","23:17":"وقال له: «لا تخف، لأن يد شاول أبي لن تطولك. وأنت ستكون ملكا على إسرائيل، وأنا أكون الرجل الثاني في المملكة. وأبي أيضا يعلم هذا الأمر».","23:18":"وجددا عهدهما أمام الرب. ومضى يوناثان إلى بيته، أما داود فمكث في الغابة.","23:19":"وجاء الزيفيون إلى شاول في جبعة وقالوا: «أليس داود مختبئا عندنا في حصون الغابة في حخيلة جنوبي الصحراء،","23:20":"فتعال إلينا أيها الملك، في أي وقت تشاء، ونحن نضمن أن نسلمه إليك».","23:21":"فأجابهم شاول: «ليبارككم الرب لرأفتكم بي؛","23:22":"فاذهبوا وتحروا وتيقنوا من مكان وجوده وإقامته ومن رآه هناك، لأنه قيل لي إن داود شديد المكر.","23:23":"وتأكدوا لي من جميع المواضع التي يمكن أن يختبئ فيها ثم ارجعوا إلي بالخبر اليقين فأمضي معكم، إن كان حقا موجودا، فأبحث عنه بين عشائر يهوذا».","23:24":"فانطلقوا إلى زيف متقدمين أمام شاول. وكان داود آنئذ في سهل برية معون جنوبي الصحراء.","23:25":"فشرع رجال شاول يبحثون عنه. فبلغ الخبر داود فتوغل في منطقة الصخور في برية معون. وعندما علم شاول بذلك تعقبه إلى هناك.","23:26":"فكان شاول يسير على محاذاة أحد جانبي الجبل، وداود ورجاله يسيرون بمحاذاة الجانب الآخر هربا من شاول، الذي سعى مع قواته لمحاصرة داود ورجاله ليأسرهم.","23:27":"وما لبث أن وفد رسول إلى شاول قائلا: «أسرع! تعال، فقد اقتحم الفلسطينيون البلاد.","23:28":"فرجع شاول عن مطاردة داود وذهب لمحاربة الفلسطينيين، لذلك دعي ذلك الموضع «تل المفارقة».","23:29":"وتوجه داود من هناك وتمنع في حصون عين جدي.","24:1":"وبعد أن رجع شاول من مطاردة الفلسطينيين قيل له: «إن داود متحصن في برية عين جدي»","24:2":"فحشد ثلاثة آلاف رجل من خيرة قوات إسرائيل وسعى وراء داود ورجاله في صخور الوعول.","24:3":"ودخل شاول كهفا عند حظيرة غنم على الطريق ليقضي حاجته، وكان داود ورجاله مختبئين في أغوار الكهف.","24:4":"فقال له رجاله: «هذا هو اليوم الذي وعدك الرب أن يسلم فيه عدوك إليك فتصنع به ما تشاء». فانسل داود إليه وقطع طرف جبته سرا.","24:5":"ولكن ما لبث قلبه أن وبخه على قطعه طرف جبة شاول.","24:6":"فقال لرجاله: «معاذ الله أن أقترف هذا الإثم بحق سيدي المختار من الرب فأمد يدي وأسيء إليه لأن الرب قد مسحه ملكا».","24:7":"وهكذا زجر داود رجاله بمثل هذا الكلام، ولم يدعهم يهاجمون شاول. وما لبث شاول أن خرج من الكهف ومضى في سبيله،","24:8":"فتبعه داود إلى خارج الكهف ونادى: «يا سيدي الملك». فالتفت شاول خلفه، فانحنى داود إلى الأرض ساجدا","24:9":"وقال: «لماذا تستمع إلى أقاويل الناس: إن داود قد وطد العزم على إيذائك.","24:10":"ها أنت قد رأيت اليوم بعينيك كيف أوقعك الرب في قبضتي عندما كنت في الكهف، وجاء من يحرضني على قتلك، ولكني أشفقت عليك وقلت: لا! لن أمد يدي بالإساءة إلى سيدي، لأن الرب هو الذي اختاره.","24:11":"فانظر يا أبي ما بيدي، إنه طرف جبتك. إن قطعي طرف جبتك وعدم قتلي إياك خير دليل على أنني لم أرتكب شرا أو ذنبا، ولم أخطئ إليك، بينما أنت تتربص بي لتقتلني.","24:12":"فليقض الرب بيني وبينك وينتقم لي الرب منك، أما أنا فلن أمسك بسوء.","24:13":"وكما قيل في مثل القدماء: عن الأشرار يصدر شر، لذلك فإن يدي لن تنالك بأذى.","24:14":"ثم وراء من يسعى ملك إسرائيل؟ من هو الذي تطارده؟ أتسعى وراء كلب ميت؟ وراء برغوث واحد؟","24:15":"ليكن الرب هو الديان فيقضي بيني وبينك ويتولى قضيتي ويبرئني وينقذني من قبضتك».","24:16":"فلما فرغ داود من الكلام تساءل شاول: «أهذا صوتك يا ابني داود؟» وارتفع صوت شاول بالبكاء.","24:17":"ثم قال لداود: «إنك حقا أبر مني لأنك كافأتني خيرا وأنا جازيتك شرا.","24:18":"وأبديت نحوي خيرا إذ إن الرب قد أوقعني في قبضتك ولكنك عفوت عني.","24:19":"أيعفو رجل عن عدوه ويطلقه من غير أن ينتقم منه بعد أن يقع في قبضته؟ فليكافئك الرب جزاء ما صنعت اليوم معي من خير.","24:20":"لقد علمت الآن أنك تصبح ملكا وبيدك تثبت مملكة إسرائيل.","24:21":"فاحلف لي الآن بالرب أنك لا تبيد نسلي من بعدي ولا تقضي على اسمي من بيت أبي».","24:22":"فحلف داود لشاول ثم مضى شاول إلى بيته، أما داود ورجاله فالتجأوا إلى الحصن.","25:1":"ومات صموئيل، فاجتمع جميع بني إسرائيل وناحوا عليه ودفنوه في بيته في الرامة. فانتقل داود إلى صحراء فاران.","25:2":"وكان هناك رجل ثري مقيم في مدينة معون ذو أملاك في الكرمل حيث كان يجز غنمه، وكانت ثروته طائلة جدا، إذ كان يمتلك ثلاثة آلاف رأس من الغنم وألفا من المعز.","25:3":"وكان اسم الرجل نابال، واسم امرأته أبيجايل. وكانت المرأة فاتنة الجمال راجحة العقل، أما الرجل فكان قاسيا سيئ الأعمال، وهو ينتمي إلى عشيرة كالب.","25:4":"فبلغ داود، وهو لا يزال في الصحراء، أن نابال يجز غنمه.","25:5":"فبعث داود بعشرة غلمان أوصاهم أن ينطلقوا إلى الكرمل ويدخلوا بيت نابال ويبلغوه تمنيات داود، ويقولوا له:","25:6":"«أطال الله بقاءك، وجعلك أنت وبيتك وكل مالك سالما.","25:7":"لقد سمعت أن عندك جزازين. حين كان رعاتك بيننا لم نؤذهم ولم يفقد لهم شيء طوال الأيام التي كانوا فيها في الكرمل.","25:8":"تحر الأمر من غلمانك فيخبروك. لذلك ليحظ غلماني برضاك، فقد جئنا إليك في يوم عيد، فهب عبيدك وابنك داود ما تجود به نفسك».","25:9":"فقدم الغلمان إلى نابال وأبلغوه هذا الكلام باسم داود وصمتوا.","25:10":"فأجابهم نابال: «من هو داود؟ ومن هو ابن يسى؟ قد كثر اليوم العبيد الهاربون من أسيادهم.","25:11":"هل آخذ خبزي ومائي وذبيحتي التي جهزتها لجازي وأعطيها لقوم لا أعلم من أين هم؟»","25:12":"فانصرف غلمان داود ورجعوا إلى داود فأخبروه بكلام نابال.","25:13":"فقال داود لرجاله: «ليتقلد كل منكم سيفه». فتقلدوا سيوفهم، وكذلك فعل داود، وسار على رأس أربع مئة رجل بعد أن مكث مئتان لحراسة الأمتعة.","25:14":"فقال أحد الغلمان لأبيجايل امرأة نابال: «بعث داود من الصحراء رسلا بتحيات إلى سيدنا فأهانهم،","25:15":"مع أن الرجال أحسنوا إلينا جدا فلم نصب بأذى أو يفقد لنا شيء طوال المدة التي تجاورنا فيها معهم ونحن في المرعى.","25:16":"كانوا سياج أمان لنا نهارا وليلا في كل الأيام التي كنا نرعى فيها الغنم في جوارهم.","25:17":"ففكري بالأمر وانظري ماذا يمكن أن تصنعي، لأن كارثة ستحل على سيدنا وعلى بيته، فهو رجل شرير لا يمكن التفاهم معه».","25:18":"فأسرعت أبيجايل وأخذت مئتي رغيف خبز وزقي خمر وخمسة خرفان مجهزة مطيبة وخمس كيلات من الفريك ومئتي عنقود زبيب ومئتي قرص تين، وحملتها على الحمير.","25:19":"وقالت لخدامها: «اسبقوني، ها أنا قادمة وراءكم». ولم تخبر رجلها نابال بما فعلت.","25:20":"وبينما كانت راكبة على حمارها عند منعطف الجبل صادفت داود ورجاله قادمين للقائها.","25:21":"وكان داود آنئذ يحدث نفسه: «لقد حافظت على كل قطعان هذا الرجل في الصحراء، فكافأني شرا بدل الخير.","25:22":"فليضاعف الرب من عقاب داود، إن لم أقض على كل رجاله قبل طلوع ضوء الصباح».","25:23":"وعندما شاهدت أبيجايل داود أسرعت وترجلت عن الحمار وخرت أمامه ساجدة،","25:24":"وانطرحت عند رجليه قائلة: «ضع اللوم علي وحدي يا سيدي، ودع أمتك تتكلم في مسامعك واصغ إلى حديثها.","25:25":"لا يضغن قلب سيدي على هذا الرجل اللئيم نابال، فهو فظ كاسمه والحماقة مقرونة به، أما أنا فلم أر رجال سيدي حين أرسلتهم.","25:26":"والآن أقسم لك بالرب الحي وبحياتك، إن الرب قد جنبك سفك الدماء والثأر لنفسك، وليكن أعداؤك ومن يسعون في هلاكك، كنابال.","25:27":"فتقبل الآن هذه البركة التي أحضرتها جاريتك يا سيدي وأعطها لرجالك الملتفين حولك.","25:28":"واعف عن ذنب أمتك، لأن الرب لابد أن يثبت كرسي ملك سيدي إلى الأبد، لأن سيدي يحارب حروب الرب، فلا يوجد فيك شر كل أيامك.","25:29":"وإن قام من يتعقبك ليقتلك، فلتكن نفس سيدي محزومة في حزمة الأحياء مع الرب إلهك. وأما نفس أعدائك فليقذف بها كما يقذف حجر من وسط كفة مقلاع.","25:30":"وعندما يحقق الرب لسيدي كل هذا الخير الذي وعد به وينصبك رئيسا على إسرائيل،","25:31":"فلن تقاسي من عذاب الضمير لأنك سفكت دماء اعتباطا أو انتقمت لنفسك. ومتى حقق لك الرب وعده فاذكر أمتك».","25:32":"فقال داود لأبيجايل: «مبارك الرب إله إسرائيل الذي أرسلك اليوم للقائي،","25:33":"ومباركة فطنتك، ومباركة أنت لأنك جنبتني اليوم سفك الدماء والانتقام لنفسي.","25:34":"ولكن حي هو الرب الذي منعني من الإساءة إليك، فلو لم تبادري وتأتي لاستقبالي لما بقي لنابال رجل على قيد الحياة عند مطلع ضوء الصباح».","25:35":"وقبل داود منها ما حملته إليه قائلا لها: «امضي إلى بيتك بسلام، فها أنا قد استمعت لتوسلك واستجبت طلبتك».","25:36":"فأقبلت أبيجايل إلى نابال، فوجدت أنه قد أقام مأدبة في بيته كمأدبة ملك، وقد أخذته النشوة بعد أن أكثر من احتساء الخمر حتى سكر، فلم تخبره بشيء إطلاقا حتى صباح اليوم التالي.","25:37":"وفي الصباح، بعد أن صحا نابال من سكرته، أخبرته بما جرى، فأصابه الشلل وتجمد كحجر.","25:38":"وبعد عشرة أيام ضربه الله فمات.","25:39":"فلما سمع داود بموت نابال قال: «مبارك الرب الذي انتقم لي بذاته من إهانة نابال، وجنبني ارتكاب الشر وعاقب نابال على إثمه». وأرسل داود إلى أبيجايل يسألها الزواج منه.","25:40":"فوفد رسل داود إلى أبيجايل إلى الكرمل وقالوا لها: «أرسلنا داود إليك لنسألك الزواج منه».","25:41":"فقامت وسجدت بوجهها إلى الأرض وقالت: «أنا أمته المستعدة لخدمته ولغسل أرجل عبيد سيدي».","25:42":"ثم أسرعت أبيجايل وركبت حمارها بعد أن صحبت معها خمس فتيات من جواريها سرن وراءها، وتبعت رسل داود، وصارت له زوجة.","25:43":"ثم تزوج داود أخينوعم من يزرعيل فكانتا له زوجتين.","25:44":"عندئذ زوج شاول ميكال ابنته امرأة داود من فلطي بن لايش الذي من جليم.","26:1":"وتوجه الزيفيون إلى شاول في جبعة وقالوا: «أليس داود مختبئا في تل حخيلة تجاه الصحراء؟»","26:2":"فاختار شاول ثلاثة آلاف رجل من خيرة جنود إسرائيل وانطلق نحو صحراء زيف ليبحث فيها عن داود.","26:3":"وعسكر شاول إزاء الطريق عند سفح تل حخيلة تجاه الصحراء، وكان داود آنئذ مقيما في الصحراء. فعندما سمع أن شاول تعقبه إلى الصحراء","26:4":"أرسل جواسيسه ليتيقن من أن شاول قد تعقبه حقا.","26:5":"ثم قام داود وتسلل إلى الموضع المضطجع فيه شاول، وأبنير بن نير رئيس جيشه. فرأى شاول راقدا عند المتراس محاطا بجنوده.","26:6":"فخاطب داود أخيمالك الحثي وأبيشاي ابن صروية (شقيق يوآب): «من منكما ينزل معي إلى معسكر شاول؟» فقال أبيشاي: «أنا أنزل معك».","26:7":"فتسلل داود وأبيشاي ليلا إلى معسكر شاول، وإذا بشاول راقد عند المتراس ورمحه مغروس في الأرض إلى جوار رأسه، وأبنير والجنود نائمون حوله.","26:8":"فقال أبيشاي لداود: «لقد أوقع الله اليوم عدوك في قبضة يدك، فدعني الآن أطعنه برمحه إلى الأرض، فأجهز عليه بضربة واحدة».","26:9":"فأجاب داود: «لا تقض عليه، إذ من يمد يده ليسيء لمسيح الرب ويتبرأ؟","26:10":"إن الرب نفسه لابد أن يعاقب شاول فيميته ميتة طبيعية، أو يقتله في معركة حربية.","26:11":"ولكن معاذ الله أن أمد يدي لأسيء إلى مسيح الرب. أما الآن فخذ الرمح المغروس عند رأسه وكوز الماء وهلم بنا من هنا».","26:12":"وهكذا أخذ داود الرمح وكوز الماء من عند رأس شاول وتسللا راجعين، من غير أن يراهما أو ينتبه لوجودهما أحد، لأنهم جميعا كانوا نياما إذ إن الرب أثقلهم بالسبات العميق.","26:13":"واجتاز داود الوادي إلى الجبل المقابل وارتقى إلى قمته حيث وقف عن بعد، تفصله عن شاول مسافة كبيرة.","26:14":"ونادى داود الجنود وأبنير بن نير قائلا: «ألا تجيبني يا أبنير؟». فأجاب أبنير: «من هذا الذي ينادي الملك؟»","26:15":"فقال داود لأبنير: «ألست أنت رجلا؟ ومن مثلك في كل إسرائيل؟ فلماذا لم تحرس سيدك الملك؟ فقد جاء من هم بقتل سيدك الملك.","26:16":"إن ما عملته لا يستحق الثناء، فحي هو الرب إنكم أبناء الموت، لأنكم لم تحرسوا سيدكم مسيح الرب، فانظر حولك الآن، أين هو رمح الملك وكوز الماء اللذان كانا عند رأسه؟».","26:17":"وتبين شاول صوت داود، فقال: «أهذا صوتك يا ابني داود؟» فأجاب داود: «إنه صوتي يا سيدي الملك».","26:18":"ثم تابع حديثه: «لماذا لايزال سيدي يسعى وراء عبده؟ أي ذنب جنيت، وأي جرم اقترفت؟","26:19":"فليسمع سيدي الملك كلام عبده الآن: إن كان الرب قد أثارك ضدي فلأقدمن له قربان رضى. وإن كان الناس هم الذين أوغروا صدرك علي فليكونوا ملعونين أمام الرب، لأنهم نفوني من أرض ميراث الرب قائلين: اذهب اعبد آلهة أخرى.","26:20":"والآن لا تدع دمي يهدر على أرض غريبة بعيدا عن حضرة الرب، لأن ملك إسرائيل قد خرج ليبحث عن برغوث واحد ويتعقبه كما يتعقب الحجل في الجبال؟».","26:21":"فقال شاول: «لقد أخطأت. ارجع يا ابني داود فلن أسيء إليك بعد اليوم، لأن نفسي كانت عزيزة في عينيك. لشد ما أخطأت وضللت!».","26:22":"فأجاب داود: «هوذا رمح الملك. فليأت أحد الرجال ويأخذه.","26:23":"وليكافئ الرب كل واحد على استقامته وأمانته، لأن الرب قد أوقعك اليوم في قبضتي، لكني لم أشأ أن أمد يدي لأسيء إلى مختار الرب.","26:24":"وكما كانت نفسك عزيزة في عيني اليوم، لتكن نفسي أيضا عزيزة في عيني الرب، وينقذني من كل ضيق».","26:25":"فقال شاول لداود: «لتكن مباركا يا ابني داود، فإنك قادر على القيام بأمور عظيمة وتنجح فيها». ثم مضى داود في حال سبيله ورجع شاول إلى بيته.","27:1":"وحدث داود نفسه: «إن بقيت في أرض إسرائيل فإن شاول لابد أن يقتلني في يوم ما. فلألجأن إلى أرض الفلسطينيين فييأس شاول مني ويكف عن البحث عني في تخوم إسرائيل فأنجو من يده».","27:2":"فارتحل داود والست مئة رجل الذين معه إلى أخيش بن معوك ملك جت.","27:3":"واستقر بهم المقام هناك، كل رجل مع أهل بيته، وكذلك رافقت داود زوجتاه أخينوعم اليزرعيلية وأبيجايل امرأة نابال الكرملية.","27:4":"ولما بلغ شاول أن داود هرب إلى جت، كف عن البحث عنه.","27:5":"وقال داود لأخيش ملك جت: «إن كنت قد حظيت برضاك فليتم تحديد قرية لي في الريف أقيم فيها. لماذا يقيم عبدك في عاصمة الملك معك؟»","27:6":"فوهبه أخيش صقلغ. لذلك صارت صقلغ ملكا لملوك يهوذا منذ ذلك الحين.","27:7":"وأقام داود في بلاد الفلسطينيين سنة وأربعة أشهر.","27:8":"وانطلق داود ورجاله يشنون الغارات على الجشوريين والجرزيين والعمالقة الذين استوطنوا من قديم الأرض الممتدة من حدود شور إلى تخوم مصر.","27:9":"وهاجم داود سكان الأرض، فلم يستبق نفسا واحدة. واستولى على الغنم والبقر والحمير والجمال والثياب، ثم رجع إلى أخيش.","27:10":"وعندما كان أخيش يسأل داود: «أين أغرت هذه المرة؟» كان يجيب: «على جنوبي يهوذا وعلى جنوبي أرض اليرحمئيليين وجنوبي القينيين».","27:11":"ولم يكن داود يستبقي رجلا أو امرأة على قيد الحياة لئلا يأتي إلى جت من يبلغ أخيش عما فعله داود. هكذا كان داود يفعل طوال مدة إقامته في بلاد الفلسطينيين.","27:12":"فصدق أخيش أخبار داود قائلا في نفسه: «لقد أصبح داود مكروها لدى قومه إسرائيل، لذلك سيظل ماكثا عندي خادما لي إلى الأبد».","28:1":"في تلك الأيام حشد الفلسطينيون جيوشهم لمحاربة الإسرائيليين، فقال أخيش لداود: «لابد أن تنضم إلى الجيش أنت ورجالك لخوض الحرب».","28:2":"فأجابه داود: «سترى بعينيك ما يصنع عبدك في الحرب». فقال أخيش لداود: «إذن أجعلك حارسي الشخصي كل الأيام».","28:3":"وكان صموئيل قد مات وناح عليه الإسرائيليون ودفنوه في الرامة مدينته، وكان شاول قد طرد العرافين ووسطاء الجن من الأرض.","28:4":"وعندما تجمعت قوات الفلسطينيين عسكروا في شونم، أما شاول فقد حشد جيوشه وخيم في جلبوع.","28:5":"وحين شاهد شاول جيش الفلسطينيين ملأ قلبه الخوف والاضطراب،","28:6":"فاستشار الرب فلم يجبه لا بأحلام ولا بالأوريم ولا عن طريق الأنبياء.","28:7":"فقال لعبيده: «ابحثوا لي عن امرأة عرافة وسيطة، فأذهب إليها وأستشيرها». فأجابه عبيده: «هناك عرافة تقيم في عين دور».","28:8":"فتنكر شاول وارتدى ثيابا أخرى وتوجه إلى بيت العرافة ليلا بصحبة اثنين من رجاله، وقال لها: «استشيري لي روحا، واستدعي لي من أسميه لك».","28:9":"فقالت له المرأة: «أنت تعلم ما فعله شاول بالوسطاء الروحانيين والعرافين، وكيف قتلهم، فلماذا تنصب لي فخا وتقتلني؟»","28:10":"فأقسم لها شاول قائلا: «حي هو الرب لن يلحق بك أي أذى من جراء هذا الأمر».","28:11":"فسألته المرأة: «من أستدعي لك؟» فأجابها: «استدعي لي صموئيل».","28:12":"وعندما شاهدت المرأة صموئيل صرخت صرخة هائلة وقالت لشاول: «لماذا خدعتني وأنت شاول؟»","28:13":"فقال لها: «لا تخافي. ماذا رأيت؟» فأجابت: «رأيت طيفا صاعدا من الأرض»","28:14":"فسألها: «كيف هيئته؟» فقالت: «رجل شيخ صاعد وهو مغطى بجبة». فأدرك شاول أنه صموئيل فخر على وجهه إلى الأرض ساجدا.","28:15":"فقال صموئيل لشاول: «لماذا أزعجتني بإصعادك لي؟». فأجاب: «إنني في ضيق شديد. الفلسطينيون يحاربونني والرب قد نبذني ولم يعد يجيبني لا عن طريق الأنبياء ولا بالأحلام. فدعوتك لترشدني».","28:16":"فسأله صموئيل: «لماذا تسألني والرب قد نبذك وصار لك عدوا؟","28:17":"وقد حقق الرب ما وعد به على لساني، فانتزع منك الملك وأعطاه لقريبك داود.","28:18":"لأنك لم تطع أمر الرب ولم تنفذ قضاءه في عماليق، لذلك عاقبك الرب في هذا اليوم،","28:19":"وسيجعل الفلسطينيون يهزمونك أنت والإسرائيليين، ويقضون على جيشك. أما أنت وبنوك فستلحقون غدا بي وتكونون معي».","28:20":"فانطرح شاول بطوله على الأرض مرعوبا من كلام صموئيل، كما زاد الجوع من إعيائه لأنه لم يكن قد تناول طعاما طوال يوم بكامله.","28:21":"وعندما رأت المرأة ما أصاب شاول من ارتياع شديد، قالت له: «ها قد سمعت جاريتك لصوتك، وحملت روحي في كفي واستجبت لكل ما طلبته مني.","28:22":"فالآن استمع أنت أيضا لسؤل جاريتك، ودعني أقدم لك طعاما لتأكل، فتسترد قوتك عندما تنطلق في سبيلك».","28:23":"فأبى قائلا: «لن آكل». ولكنها ألحت عليه كما ألح عليه عبداه، فأذعن لهم وقام عن الأرض وجلس على السرير.","28:24":"وكان لدى المرأة عجل مسمن فبادرت إليه وذبحته وأخذت دقيقا وعجنته وخبزت فطيرا.","28:25":"ثم وضعته أمام شاول ورجليه فأكلوا، ثم انصرفوا من عندها في تلك الليلة.","29:1":"ثم حشد الفلسطينيون جيوشهم في أفيق بينما تجمع الإسرائيليون عند العين التي في يزرعيل.","29:2":"وتقدم قادة الفلسطينيين بكتائبهم وسراياهم، أما داود ورجاله فكانوا يسيرون في المؤخرة مع الملك أخيش.","29:3":"فسأله قادة الفلسطينيين: «ماذا يفعل هؤلاء العبرانيون هنا؟» فأجابهم أخيش: «أليس هذا داود الذي كان ضابطا عند شاول ملك إسرائيل، وقد مكث معي طوال هذه المدة، فلم أجد فيه علة منذ أن قدم إلي وحتى هذا اليوم».","29:4":"غير أن قادة الفلسطينيين أبدوا سخطهم عليه قائلين: «أرجع الرجل إلى موضعه الذي حددته له، ولا تدعه يشترك معنا في الحرب لئلا ينقلب علينا. إذ كيف يسترد هذا رضى سيده؟ أليس بقطع رؤوس رجالنا؟","29:5":"أليس هذا هو داود الذي غنت له النساء راقصات قائلات: قتل شاول ألوفا، وقتل داود عشرات الألوف؟»","29:6":"فاستدعى أخيش داود وقال له: «أقسم لك بالرب الحي إنك مستقيم، ويسرني انضمامك إلى جيشي لأنني لم أجد فيك علة منذ أن جئت إلي حتى هذا اليوم، غير أن قادة جيشي ساخطون عليك.","29:7":"فامض الآن بسلام وعد إلى موضعك ولا تقترف ما يسيء إلى أقطاب الفلسطينيين».","29:8":"فقال داود: «ماذا جنيت، وأي علة وجدت في عبدك منذ أن مثلت أمامك إلى اليوم حتى لا أشترك في محاربة أعداء سيدي الملك؟»","29:9":"فقال أخيش: «إنني واثق أنك صالح في عيني، كملاك الله، غير أن رؤساء الفلسطينيين أصروا قائلين: لا يصعد داود معنا لخوض الحرب.","29:10":"لذلك بكر صباحا مع عبيد سيدك الذين وفدوا معك وارجعوا عند طلوع الصباح».","29:11":"فاستيقظ داود ورجاله مبكرين ليرجعوا إلى بلاد الفلسطينيين، وأما الفلسطينيون فتقدموا نحو يزرعيل.","30:1":"وما إن وصل داود ورجاله إلى صقلغ في اليوم الثالث حتى وجدوا أن العمالقة قد أغاروا على النقب وهاجموا صقلغ وأحرقوها بالنار،","30:2":"بعد أن أخذوا كل من فيها من نساء وأطفال أسرى حرب، ولم يقتلوا صغيرا ولا كبيرا.","30:3":"وعندما دخل داود ورجاله إلى المدينة وجدوها محروقة، وأسرت نساؤهم وبناتهم وأبناؤهم.","30:4":"فعلت أصواتهم بالبكاء حتى أصابهم الإعياء.","30:5":"وكانت امرأتا داود أخينوعم اليزرعيلية وأبيجايل أرملة نابال الكرملي من جملة المسبيات.","30:6":"وتفاقم ضيق داود لأن الرجال، من فرط ما حل بهم من مرارة وأسى على أبنائهم وبناتهم، طالبوا برجمه، غير أن داود تشبث وتقوى بالرب إلهه.","30:7":"ثم قال داود لأبياثار الكاهن ابن أخيمالك: «أحضر إلي الأفود». فأحضره.","30:8":"واستشار داود الرب قائلا: «إذا تعقبت هؤلاء الغزاة فهل أدركهم؟» فقال له: «الحقهم، فإنك تدركهم وتنقذ الأسرى».","30:9":"فانطلق داود والست مئة رجل الذين معه حتى بلغوا وادي البسور، فتخلف قوم منهم هناك.","30:10":"أما داود فواصل طريقه مع أربع مئة رجل، بعد أن تخلف مئتا رجل إعياء عن عبور وادي البسور.","30:11":"فصادفوا رجلا مصريا ملقى في الحقل، فأحضروه إلى داود، فقدموا إليه طعاما وماء فأكل وشرب.","30:12":"ثم أعطوه قرصا من تين وعنقودين من زبيب. وبعد أن أكلها انتعشت روحه، لأنه لم يكن قد أكل طعاما ولا شرب ماء منذ ثلاثة أيام وثلاث ليال.","30:13":"فسأله داود: «من هو سيدك ومن أين أنت؟» فأجاب: «أنا رجل مصري، عبد لرجل عماليقي، وقد تخلى سيدي عني منذ ثلاثة أيام لأني مرضت.","30:14":"فإننا قد أغرنا على جنوبي بلاد الكريتيين وعلى جنوبي أرض يهوذا وجنوبي كالب وأحرقنا صقلغ بالنار»","30:15":"فسأله داود: «هل تدلني على مكان هؤلاء الغزاة؟» فأجابه: «احلف لي بالله أنك لا تقتلني ولا تسلمني إلى سيدي، فأدلك على مكان هؤلاء الغزاة».","30:16":"وقادهم إلى معسكر عماليق فوجدوهم منتشرين في الحقول يأكلون ويشربون ويرقصون من جراء ما أصابوه من غنيمة عظيمة نهبوها من أرض الفلسطينيين ومن أرض يهوذا.","30:17":"فهاجمهم داود من الغروب حتى مساء اليوم التالي، ولم ينج منهم أحد سوى أربع مئة غلام ركبوا جمالا وهربوا.","30:18":"واسترد داود ما استولى عليه العمالقة وأنقذ زوجتيه.","30:19":"ولم يفقد لهم شيء لا صغير ولا كبير، ولا أبناء ولا بنات ولا غنيمة ولا أي شيء مما استولى عليه العمالقة، بل استردها داود جميعها.","30:20":"وأخذ داود غنم العمالقة وبقرهم فساقها رجاله أمام الماشية الأخرى التي اغتنمها الغزاة قائلين: «هذه غنيمة داود».","30:21":"وعاد داود إلى المئتي رجل الذين أعيوا عن المسير وراءه فخلفوهم عند وادي البسور، فخرجوا لاستقبال داود ومن معه من الشعب، فتقدم داود إليهم ليطمئن على سلامتهم.","30:22":"غير أن فئة من المشاغبين من رجال داود ممن اشتركوا معه في الحرب اعترضوا قائلين: «ليأخذ كل رجل منهم امرأته وأبناءه ويمض، أما الغنيمة التي استرددناها، فلا نعطيهم منها لأنهم لم يذهبوا معنا».","30:23":"فقال داود: «لا تفعلوا هكذا يا إخوتي، لأن الرب قد أنعم علينا وحفظنا ونصرنا على الغزاة الذين أغاروا علينا.","30:24":"ومن يوافقكم على هذا الأمر؟ لأن نصيب المقيم عند الأمتعة لحراستها كنصيب من خاض الحرب، إذ تقسم الغنيمة بينهم بالسوية».","30:25":"ومنذ ذلك الحين جعل داود هذه الفريضة سنة تسري على إسرائيل إلى هذا اليوم.","30:26":"وعندما رجع داود إلى صقلغ أرسل جزءا من الغنيمة إلى أصحابه من شيوخ يهوذا قائلا: «هذه لكم هدية بركة من غنائم أعداء الرب».","30:27":"وقد بعث بها إلى الذين في بيت إيل، وفي راموت الجنوب، وفي يتير.","30:28":"وفي عروعير، وفي سفموث، وفي أشتموع.","30:29":"وفي راخال، وفي مدن اليرحمئيليين، وفي مدن القينيين،","30:30":"وفي حرمة وفي كور عاشان، وفي عتاك،","30:31":"وفي حبرون، وإلى سائر الأماكن التي تردد عليها داود ورجاله.","31:1":"وحارب الفلسطينيون بني إسرائيل على جبل جلبوع، فقتل منهم جمع غفير وهرب الباقون.","31:2":"وتعقب الفلسطينيون شاول وأبناءه، فقتلوا منهم يوناثان وأبيناداب وملكيشوع.","31:3":"واشتدت المعركة حول شاول، وأثخن رماة السهام شاول بالجراح.","31:4":"فقال شاول لحامل سلاحه: «استل سيفك واقتلني به، لئلا يأتي هؤلاء الغلف ويطعنوني ويشوهوني». فأبى حامل سلاحه الانصياع لطلب سيده خوفا، فأخذ شاول السيف ووقع عليه.","31:5":"وعندما شاهد حامل سلاحه أن شاول قد مات، وقع هو أيضا على سيفه ومات.","31:6":"وهكذا مات في ذلك اليوم شاول وأبناؤه الثلاثة وحامل سلاحه وجميع رجاله معا.","31:7":"وحين رأى رجال إسرائيل المقيمين على محاذاة الوادي وعبر الأردن أن جيش إسرائيل قد هرب، وأن شاول وأبناءه قد ماتوا، هجروا المدن وفروا. فأتى الفلسطينيون وسكنوا فيها.","31:8":"وعندما جاء الفلسطينيون في اليوم التالي ليسلبوا القتلى عثروا على شاول وعلى أبنائه الثلاثة صرعى في جبل جلبوع،","31:9":"فقطعوا رأس شاول ونزعوا سلاحه، وبعثوا يبشرون في جميع أرجاء بلاد الفلسطينيين وفي معابدهم وبين قومهم.","31:10":"ووضعوا سلاحه في معبد عشتاروث، وسمروا جسده على سور بيت شان.","31:11":"وحين بلغ أهل يابيش جلعاد ما فعله الفلسطينيون بجثة شاول،","31:12":"هب كل المحاربين الصناديد وساروا الليل كله، وأنزلوا جثة شاول وجثث أبنائه عن سور بيت شان، ونقلوها إلى يابيش وأحرقوها هناك.","31:13":"ثم جمعوا عظامهم ودفنوها تحت الأثلة في يابيش، وصاموا سبعة أيام."};
